insert into public.systems ("id", "name", "summary", "introduction", "status", "major_organs", "major_structures", "functions", "structural_adaptations", "physiological_relationships", "related_systems", "learning_objectives", "revision_questions", "references", "bundle_ids", "sort_order") select "id", "name", "summary", "introduction", "status", "major_organs", "major_structures", "functions", "structural_adaptations", "physiological_relationships", "related_systems", "learning_objectives", "revision_questions", "references", "bundle_ids", "sort_order" from jsonb_populate_recordset(null::public.systems, $j$[{"id":"cardiovascular","name":"Cardiovascular system","summary":"The heart and blood vessels that circulate blood, carrying oxygen, nutrients, hormones and waste.","introduction":"The cardiovascular system consists of the heart, a muscular pump, and a closed network of blood vessels. The right side of the heart pumps blood through the pulmonary circulation to the lungs; the left side pumps blood through the systemic circulation to the rest of the body. Valves keep blood moving in one direction, and an intrinsic conducting system coordinates each heartbeat.","status":"demonstration","major_organs":["Heart","Aorta and great arteries","Venae cavae","Pulmonary vessels"],"major_structures":["Right atrium","Right ventricle","Left atrium","Left ventricle","Heart valves","Aorta","Pulmonary trunk","Superior and inferior vena cava","Coronary arteries","Sinoatrial node"],"functions":["Transport oxygen and carbon dioxide","Distribute nutrients and hormones","Remove metabolic waste to organs of excretion","Contribute to temperature regulation and immune cell transport","Maintain arterial blood pressure and tissue perfusion"],"structural_adaptations":["Thick left ventricular wall generates the high pressure of the systemic circulation.","Elastic arteries (such as the aorta) stretch in systole and recoil in diastole, smoothing pulsatile flow.","Venous valves and the skeletal muscle pump promote return of blood to the heart against gravity.","Intercalated discs with gap junctions allow cardiac muscle to contract as a coordinated unit."],"physiological_relationships":["Works with the respiratory system to load oxygen and unload carbon dioxide in the lungs.","Kidneys regulate blood volume and pressure (renin-angiotensin-aldosterone system).","The autonomic nervous system adjusts heart rate and vessel tone.","The endocrine system (e.g. adrenaline, antidiuretic hormone) modulates output and vascular resistance."],"related_systems":["respiratory","nervous","urinary","endocrine","lymphatic"],"learning_objectives":["Name the four heart chambers and trace blood through the heart and both circulations.","Describe the structure and function of the four heart valves.","Relate the structure of each chamber and vessel to its function.","Describe the phases of the cardiac cycle and the conduction system.","Identify cardiac muscle histology and explain the role of intercalated discs."],"revision_questions":[{"question":"Which side of the heart receives oxygenated blood from the lungs?","answer":"The left side: the pulmonary veins drain into the left atrium."},{"question":"Why is the left ventricular wall thicker than the right?","answer":"It pumps blood against the much higher resistance of the systemic circulation, so it needs more myocardium to generate pressure."}],"references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Further reading. Content on this platform is an original summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)","note":"Further reading."},{"title":"Guyton and Hall Textbook of Medical Physiology","source":"Hall & Hall (Elsevier)","note":"Further reading."}],"bundle_ids":["heart","vessels"],"sort_order":0},{"id":"skeletal","name":"Skeletal system","summary":"Bones, cartilage and joints that support the body, protect organs, enable movement and store minerals.","introduction":"The adult skeleton is usually described as 206 bones, divided into the axial skeleton (skull, vertebral column and thoracic cage) and the appendicular skeleton (pectoral and pelvic girdles and the limbs). Bone is a living, remodelling tissue. Bones articulate at joints, and muscles attach to them to produce movement.","status":"demonstration","major_organs":["Skull","Vertebral column","Thoracic cage","Pectoral girdle and upper limb","Pelvic girdle and lower limb"],"major_structures":["Skull","Vertebral column","Ribs and sternum","Clavicle","Scapula","Humerus","Radius and ulna","Pelvis (hip bone)","Femur","Patella","Tibia and fibula"],"functions":["Support and body shape","Protection of vital organs (brain, spinal cord, heart, lungs, pelvic organs)","Attachment and leverage for muscles","Storage of calcium and phosphate","Haematopoiesis in red bone marrow"],"structural_adaptations":["Compact bone in the shaft of long bones resists bending and torsion.","Spongy (trabecular) bone at the ends of long bones distributes load and reduces weight.","The curves of the vertebral column increase its resilience and help balance the trunk.","The rib cage is flexible because of costal cartilages, allowing breathing movements."],"physiological_relationships":["Muscles pull on bones across joints to produce movement.","Bone is a calcium reservoir regulated by parathyroid hormone, calcitonin and vitamin D.","Red bone marrow produces blood cells, linking bone to the cardiovascular and immune systems."],"related_systems":["muscular","cardiovascular","endocrine","nervous"],"learning_objectives":["Divide the skeleton into axial and appendicular parts and name the main bones of each.","Classify bones by shape (long, short, flat, irregular, sesamoid) with examples.","Describe the gross and microscopic structure of a long bone.","Name the regions and curvatures of the vertebral column.","Describe the articulations of the major bones of the limbs."],"revision_questions":[{"question":"Which bones form the axial skeleton?","answer":"The skull, vertebral column and thoracic cage (ribs and sternum)."},{"question":"What type of bone is the patella?","answer":"A sesamoid bone: it develops within the quadriceps tendon."}],"references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Further reading. Content on this platform is an original summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)","note":"Further reading."},{"title":"Histology: A Text and Atlas","source":"Pawlina (Wolters Kluwer)","note":"Further reading."}],"bundle_ids":["skeleton","joints"],"sort_order":1},{"id":"muscular","name":"Muscular system","summary":"Skeletal, cardiac and smooth muscle that produce movement, maintain posture and generate heat.","introduction":"Muscle tissue is specialised for contraction. Skeletal muscle is voluntary and attached to bones by tendons; cardiac muscle forms the wall of the heart; smooth muscle lies in the walls of hollow organs and vessels. Skeletal muscles act across joints, often in groups of agonists, antagonists and synergists.","status":"introductory","major_organs":["Skeletal muscles","Diaphragm","Cardiac muscle (myocardium)"],"major_structures":["Muscle belly","Tendon","Aponeurosis","Motor unit"],"functions":["Movement of the body and its parts","Posture and joint stabilisation","Heat production","Movement of substances (heart, gut, vessels)"],"structural_adaptations":["Sarcomeres arranged in series give skeletal muscle its striated appearance and the ability to shorten."],"physiological_relationships":["Controlled by the nervous system through motor neurons at neuromuscular junctions.","Depends on the cardiovascular and respiratory systems for oxygen supply."],"related_systems":["skeletal","nervous","cardiovascular"],"learning_objectives":["Distinguish skeletal, cardiac and smooth muscle.","Describe the sliding-filament mechanism at a basic level.","Define origin, insertion and the roles of agonists and antagonists."],"revision_questions":[{"question":"What connects skeletal muscle to bone?","answer":"Tendons, made mainly of dense regular connective tissue."}],"references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Further reading. Content on this platform is an original summary."},{"title":"Guyton and Hall Textbook of Medical Physiology","source":"Hall & Hall (Elsevier)","note":"Further reading."}],"bundle_ids":["muscles","fasciae"],"sort_order":2},{"id":"nervous","name":"Nervous system","summary":"The brain, spinal cord and nerves that sense, integrate and coordinate the body.","introduction":"The nervous system is divided into the central nervous system (brain and spinal cord) and the peripheral nervous system (cranial and spinal nerves and ganglia). Functionally, the peripheral system includes somatic and autonomic divisions; the autonomic division has sympathetic and parasympathetic parts.","status":"introductory","major_organs":["Brain","Spinal cord","Cranial nerves","Spinal nerves","Autonomic ganglia"],"major_structures":["Cerebrum","Cerebellum","Brainstem","Meninges"],"functions":["Sensation","Integration and decision making","Motor control","Autonomic regulation of internal organs"],"structural_adaptations":["Myelination of axons increases conduction velocity."],"physiological_relationships":["Controls heart rate, breathing and gut motility through the autonomic system.","Works with the endocrine system in neuroendocrine control."],"related_systems":["endocrine","muscular","sensory"],"learning_objectives":["Divide the nervous system into CNS and PNS.","Name the three meningeal layers.","Distinguish sympathetic from parasympathetic actions."],"revision_questions":[{"question":"What are the three meninges, from outside to inside?","answer":"Dura mater, arachnoid mater and pia mater."}],"references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Further reading. Content on this platform is an original summary."},{"title":"Guyton and Hall Textbook of Medical Physiology","source":"Hall & Hall (Elsevier)","note":"Further reading."}],"bundle_ids":["cns","pns"],"sort_order":3},{"id":"respiratory","name":"Respiratory system","summary":"Airways and lungs that exchange oxygen and carbon dioxide between air and blood.","introduction":"The respiratory system conducts air from the nose and mouth through the pharynx, larynx, trachea and bronchial tree to the alveoli, where gas exchange occurs. Breathing is driven mainly by the diaphragm and intercostal muscles changing thoracic volume.","status":"introductory","major_organs":["Nose","Pharynx","Larynx","Trachea","Bronchi","Lungs","Diaphragm"],"major_structures":["Alveoli","Bronchial tree","Pleura"],"functions":["Gas exchange","Acid-base balance","Phonation","Filtering and humidifying inspired air"],"structural_adaptations":["Alveolar walls are extremely thin (simple squamous epithelium) and surrounded by capillaries, favouring diffusion."],"physiological_relationships":["Works with the cardiovascular system to match ventilation with perfusion."],"related_systems":["cardiovascular","muscular","nervous"],"learning_objectives":["Trace the path of air to the alveoli.","Describe how the diaphragm changes thoracic volume.","Name the lobes of each lung."],"revision_questions":[{"question":"How many lobes does each lung have?","answer":"The right lung has three lobes; the left lung has two (and a lingula)."}],"references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Further reading. Content on this platform is an original summary."},{"title":"Guyton and Hall Textbook of Medical Physiology","source":"Hall & Hall (Elsevier)","note":"Further reading."}],"bundle_ids":["respiratory"],"sort_order":4},{"id":"digestive","name":"Digestive system","summary":"The gastrointestinal tract and accessory organs that digest food and absorb nutrients.","introduction":"The digestive system comprises the gastrointestinal tract, from mouth to anus, and accessory organs: the salivary glands, liver, gallbladder and pancreas. Mechanical and chemical digestion break food down, the small intestine is the main site of absorption, and the large intestine reabsorbs water and forms faeces.","status":"introductory","major_organs":["Oesophagus","Stomach","Small intestine","Large intestine","Liver","Pancreas","Gallbladder"],"major_structures":["Mucosa","Submucosa","Muscularis externa","Serosa/adventitia"],"functions":["Ingestion","Digestion","Absorption","Elimination"],"structural_adaptations":["Villi and microvilli of the small intestine greatly increase absorptive surface area."],"physiological_relationships":["Absorbed nutrients enter the hepatic portal system and the lymphatic system (lacteals)."],"related_systems":["lymphatic","endocrine","nervous"],"learning_objectives":["List the four layers of the gut wall.","Explain the roles of the accessory organs.","Describe peristalsis."],"revision_questions":[{"question":"Where does most nutrient absorption occur?","answer":"In the small intestine."}],"references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Further reading. Content on this platform is an original summary."},{"title":"Guyton and Hall Textbook of Medical Physiology","source":"Hall & Hall (Elsevier)","note":"Further reading."}],"bundle_ids":["digestive"],"sort_order":5},{"id":"urinary","name":"Urinary system","summary":"Kidneys and urinary tract that filter blood, regulate fluid balance and excrete waste.","introduction":"The urinary system consists of two kidneys, two ureters, the urinary bladder and the urethra. The nephron is the functional unit of the kidney and carries out filtration, reabsorption and secretion to form urine.","status":"introductory","major_organs":["Kidneys","Ureters","Urinary bladder","Urethra"],"major_structures":["Nephron","Renal cortex","Renal medulla","Renal pelvis"],"functions":["Filtration of blood","Fluid and electrolyte balance","Acid-base regulation","Excretion of waste","Endocrine roles (e.g. erythropoietin, renin)"],"structural_adaptations":["Glomerular capillaries have a fenestrated endothelium and specialised filtration barrier."],"physiological_relationships":["Regulates blood volume and pressure with the cardiovascular system."],"related_systems":["cardiovascular","endocrine"],"learning_objectives":["Trace urine from the kidney to the exterior.","Name the functional unit of the kidney."],"revision_questions":[{"question":"What is the functional unit of the kidney?","answer":"The nephron."}],"references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Further reading. Content on this platform is an original summary."},{"title":"Guyton and Hall Textbook of Medical Physiology","source":"Hall & Hall (Elsevier)","note":"Further reading."}],"bundle_ids":["urinary"],"sort_order":6},{"id":"reproductive","name":"Reproductive system","summary":"Organs involved in gamete production, reproduction and sex hormone secretion.","introduction":"The male reproductive system produces and delivers sperm; the female reproductive system produces oocytes, provides the environment for fertilisation and development of the embryo and fetus, and supports lactation. Both are regulated by the hypothalamic-pituitary-gonadal axis.","status":"introductory","major_organs":["Testes","Epididymis","Vas deferens","Prostate","Ovaries","Uterine tubes","Uterus","Vagina"],"major_structures":["Seminiferous tubules","Ovarian follicles","Endometrium","Myometrium"],"functions":["Gametogenesis","Sex hormone production","Fertilisation and gestation","Lactation"],"structural_adaptations":["The scrotum positions the testes slightly below core body temperature, which supports spermatogenesis."],"physiological_relationships":["Strongly linked to the endocrine system."],"related_systems":["endocrine","urinary"],"learning_objectives":["Name the main organs of each reproductive tract.","Describe the layers of the uterine wall."],"revision_questions":[{"question":"What are the layers of the uterine wall?","answer":"Endometrium, myometrium and perimetrium."}],"references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Further reading. Content on this platform is an original summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)","note":"Further reading."}],"bundle_ids":["reproductive"],"sort_order":7},{"id":"endocrine","name":"Endocrine system","summary":"Glands that secrete hormones into the blood to regulate metabolism, growth and homeostasis.","introduction":"Endocrine glands release hormones directly into the bloodstream. Major glands include the hypothalamus, pituitary, thyroid, parathyroids, adrenals, pancreatic islets and gonads. Many are controlled by negative feedback loops.","status":"introductory","major_organs":["Hypothalamus","Pituitary gland","Thyroid gland","Parathyroid glands","Adrenal glands","Pancreas (islets)","Gonads"],"major_structures":["Anterior pituitary","Posterior pituitary","Adrenal cortex","Adrenal medulla"],"functions":["Regulation of metabolism","Growth and development","Fluid and electrolyte balance","Stress response","Reproduction"],"structural_adaptations":["Endocrine glands are richly vascularised, often with fenestrated capillaries, to receive and release hormones."],"physiological_relationships":["Integrated with the nervous system through the hypothalamus."],"related_systems":["nervous","reproductive","urinary"],"learning_objectives":["List the major endocrine glands.","Explain negative feedback with one example."],"revision_questions":[{"question":"Which gland is sometimes called the \"master gland\"?","answer":"The pituitary gland (although it is itself controlled by the hypothalamus)."}],"references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Further reading. Content on this platform is an original summary."},{"title":"Guyton and Hall Textbook of Medical Physiology","source":"Hall & Hall (Elsevier)","note":"Further reading."}],"bundle_ids":["endocrine"],"sort_order":8},{"id":"lymphatic","name":"Lymphatic and immune system","summary":"Lymph vessels, nodes and lymphoid organs that return fluid and defend against infection.","introduction":"The lymphatic system returns interstitial fluid to the bloodstream, absorbs dietary fats from the gut, and houses immune cells. Its organs include lymph nodes, the spleen, thymus, tonsils and mucosa-associated lymphoid tissue.","status":"introductory","major_organs":["Lymph nodes","Spleen","Thymus","Tonsils","Lymphatic vessels"],"major_structures":["Thoracic duct","Right lymphatic duct","Lymph follicles"],"functions":["Fluid return","Immune surveillance","Fat absorption (lacteals)"],"structural_adaptations":["Lymphatic vessels contain valves to ensure one-way flow."],"physiological_relationships":["Drains into the venous system near the junction of the internal jugular and subclavian veins."],"related_systems":["cardiovascular","digestive"],"learning_objectives":["Describe lymph formation and return.","Name the primary and secondary lymphoid organs."],"revision_questions":[{"question":"Where does the thoracic duct drain?","answer":"Into the venous system at the junction of the left subclavian and left internal jugular veins."}],"references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Further reading. Content on this platform is an original summary."},{"title":"Histology: A Text and Atlas","source":"Pawlina (Wolters Kluwer)","note":"Further reading."}],"bundle_ids":["lymphatic"],"sort_order":9},{"id":"integumentary","name":"Integumentary system","summary":"The skin and its appendages, forming the protective outer covering of the body.","introduction":"The integument consists of the skin (epidermis and dermis) and appendages such as hair, nails and glands. The hypodermis lies deep to the dermis. The skin protects against pathogens and water loss, senses touch and temperature, and helps regulate body temperature.","status":"introductory","major_organs":["Skin","Hair","Nails","Sweat and sebaceous glands"],"major_structures":["Epidermis","Dermis","Hypodermis"],"functions":["Barrier protection","Thermoregulation","Sensation","Vitamin D synthesis"],"structural_adaptations":["The epidermis is a keratinised stratified squamous epithelium, which resists abrasion and limits water loss."],"physiological_relationships":["Sweat gland activity and dermal blood flow contribute to temperature regulation."],"related_systems":["nervous","cardiovascular"],"learning_objectives":["Name the layers of the skin.","Explain the role of keratin."],"revision_questions":[{"question":"What type of epithelium forms the epidermis?","answer":"Keratinised stratified squamous epithelium."}],"references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Further reading. Content on this platform is an original summary."},{"title":"Histology: A Text and Atlas","source":"Pawlina (Wolters Kluwer)","note":"Further reading."}],"bundle_ids":[],"sort_order":10},{"id":"sensory","name":"Special sensory organs","summary":"The eye, ear, nose and tongue and the receptors for vision, hearing, balance, smell and taste.","introduction":"The special senses are vision, hearing and balance, olfaction and gustation. Each has specialised receptor cells and cranial nerve pathways to the brain. The ear contains both the cochlea (hearing) and the vestibular apparatus (balance).","status":"introductory","major_organs":["Eye","Ear","Nose (olfactory epithelium)","Tongue"],"major_structures":["Retina","Cochlea","Vestibular apparatus","Olfactory epithelium","Taste buds"],"functions":["Vision","Hearing","Balance","Smell","Taste"],"structural_adaptations":["The retina contains rods and cones specialised for dim-light and colour vision respectively."],"physiological_relationships":["Signals reach the brain via cranial nerves."],"related_systems":["nervous"],"learning_objectives":["Name the layers of the eyeball.","Name the parts of the ear."],"revision_questions":[{"question":"Which cells of the retina mediate colour vision?","answer":"Cone photoreceptors."}],"references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Further reading. Content on this platform is an original summary."},{"title":"Guyton and Hall Textbook of Medical Physiology","source":"Hall & Hall (Elsevier)","note":"Further reading."}],"bundle_ids":["sensory"],"sort_order":11}]$j$::jsonb) on conflict do nothing;
insert into public.regions ("id", "name", "description") select "id", "name", "description" from jsonb_populate_recordset(null::public.regions, $j$[{"id":"head","name":"Head","description":"The cranium and facial skeleton, housing the brain and special sense organs."},{"id":"neck","name":"Neck","description":"The cervical region linking the head to the trunk."},{"id":"thorax","name":"Thorax","description":"The chest: thoracic cage, heart, lungs, great vessels and oesophagus."},{"id":"back","name":"Back (vertebral column)","description":"The vertebral column and associated muscles, enclosing the spinal cord."},{"id":"abdomen","name":"Abdomen","description":"The region between the thorax and pelvis containing most digestive organs."},{"id":"pelvis","name":"Pelvis","description":"The bony pelvis and the pelvic viscera."},{"id":"upper-limb","name":"Upper limb","description":"Shoulder, arm, forearm and hand."},{"id":"lower-limb","name":"Lower limb","description":"Hip, thigh, leg, ankle and foot."}]$j$::jsonb) on conflict do nothing;
insert into public.organs ("id", "name", "system_id", "region_id", "description", "structure_ids") select "id", "name", "system_id", "region_id", "description", "structure_ids" from jsonb_populate_recordset(null::public.organs, $j$[{"id":"heart","name":"Heart","system_id":"cardiovascular","region_id":"thorax","description":"A four-chambered muscular pump lying in the middle mediastinum, enclosed in the pericardium.","structure_ids":["right-atrium","right-ventricle","left-atrium","left-ventricle","tricuspid-valve","mitral-valve","aortic-valve","pulmonary-valve","sinoatrial-node","coronary-arteries","cardiac-muscle"]},{"id":"great-vessels","name":"Great vessels","system_id":"cardiovascular","region_id":"thorax","description":"The large arteries and veins that connect directly to the heart.","structure_ids":["aorta","pulmonary-trunk","superior-vena-cava","inferior-vena-cava","pulmonary-veins"]},{"id":"skull-unit","name":"Skull","system_id":"skeletal","region_id":"head","description":"The cranium (protecting the brain) and the facial skeleton, including the mandible.","structure_ids":["skull"]},{"id":"vertebral-column-unit","name":"Vertebral column","system_id":"skeletal","region_id":"back","description":"A flexible column of vertebrae that supports the trunk and encloses the spinal cord.","structure_ids":["vertebral-column"]},{"id":"thoracic-cage-unit","name":"Thoracic cage","system_id":"skeletal","region_id":"thorax","description":"The ribs, costal cartilages, thoracic vertebrae and sternum.","structure_ids":["rib-cage","sternum"]},{"id":"pectoral-girdle-unit","name":"Pectoral girdle and upper limb","system_id":"skeletal","region_id":"upper-limb","description":"The clavicle and scapula, which connect the upper limb to the axial skeleton, and the bones of the arm and forearm.","structure_ids":["clavicle","scapula","humerus","radius","ulna"]},{"id":"pelvic-girdle-unit","name":"Pelvic girdle and lower limb","system_id":"skeletal","region_id":"lower-limb","description":"The hip bones, which connect the lower limb to the axial skeleton, and the bones of the thigh and leg.","structure_ids":["pelvis","femur","patella","tibia","fibula"]}]$j$::jsonb) on conflict do nothing;
insert into public.structures ("system_id", "region_id", "references", "id", "anatomical_name", "common_name", "synonyms", "organ_id", "classification", "location", "internal_characteristics", "structural_adaptations", "functions", "blood_supply", "clinical_relevance", "related_structures", "difficulty_level", "external_characteristics", "nerve_supply", "articulations") select "system_id", "region_id", "references", "id", "anatomical_name", "common_name", "synonyms", "organ_id", "classification", "location", "internal_characteristics", "structural_adaptations", "functions", "blood_supply", "clinical_relevance", "related_structures", "difficulty_level", "external_characteristics", "nerve_supply", "articulations" from jsonb_populate_recordset(null::public.structures, $j$[{"system_id":"cardiovascular","region_id":"thorax","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Standard textbook; this entry is an original educational summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)"}],"id":"right-atrium","anatomical_name":"Right atrium","common_name":"Right upper chamber of the heart","synonyms":["atrium dextrum","RA"],"organ_id":"heart","classification":"Heart chamber (receiving chamber)","location":"Forms the right border of the heart; lies to the right of the left atrium and above the right ventricle.","internal_characteristics":["Smooth-walled posterior part (sinus venarum) receives the venae cavae and coronary sinus.","Rough anterior wall with pectinate muscles, and a right auricle.","The interatrial septum bears the fossa ovalis, a remnant of the fetal foramen ovale."],"structural_adaptations":["Thin wall, because it only has to move blood a short distance into the right ventricle at low pressure.","The auricle increases capacity."],"functions":["Receives deoxygenated blood from the superior vena cava, inferior vena cava and coronary sinus.","Passes blood to the right ventricle through the tricuspid valve.","Contains the sinoatrial node, the heart's normal pacemaker."],"blood_supply":"Mainly the right coronary artery.","clinical_relevance":["The right atrium is the usual target for central venous catheters introduced via the superior vena cava.","Atrial septal defects involve a persistent opening in the interatrial septum."],"related_structures":["right-ventricle","tricuspid-valve","sinoatrial-node","superior-vena-cava","inferior-vena-cava"],"difficulty_level":"beginner"},{"system_id":"cardiovascular","region_id":"thorax","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Standard textbook; this entry is an original educational summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)"}],"id":"right-ventricle","anatomical_name":"Right ventricle","common_name":"Right lower chamber of the heart","synonyms":["ventriculus dexter","RV"],"organ_id":"heart","classification":"Heart chamber (pumping chamber, pulmonary circuit)","location":"Forms most of the anterior (sternocostal) surface of the heart.","internal_characteristics":["Trabeculae carneae line the inflow part.","Papillary muscles connect via chordae tendineae to the tricuspid valve cusps.","A smooth outflow part (conus arteriosus) leads to the pulmonary valve.","The moderator band carries part of the conducting system across the cavity."],"structural_adaptations":["Wall about a third the thickness of the left ventricle, because the pulmonary circulation is a low-resistance, low-pressure circuit.","Crescent-shaped cavity wraps around the bulging interventricular septum."],"functions":["Receives blood from the right atrium.","Pumps deoxygenated blood through the pulmonary valve into the pulmonary trunk to the lungs."],"blood_supply":"Mainly the right coronary artery and its marginal branch; the anterior interventricular artery supplies the anterior part.","clinical_relevance":["Pulmonary hypertension increases the afterload on the right ventricle and can cause right ventricular hypertrophy and failure.","Its anterior position makes it the chamber most likely to be injured in penetrating chest trauma."],"related_structures":["right-atrium","tricuspid-valve","pulmonary-valve","pulmonary-trunk","left-ventricle"],"difficulty_level":"beginner"},{"system_id":"cardiovascular","region_id":"thorax","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Standard textbook; this entry is an original educational summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)"}],"id":"left-atrium","anatomical_name":"Left atrium","common_name":"Left upper chamber of the heart","synonyms":["atrium sinistrum","LA"],"organ_id":"heart","classification":"Heart chamber (receiving chamber)","location":"Forms most of the base (posterior surface) of the heart.","internal_characteristics":["Smooth-walled posterior part receives typically four pulmonary veins.","A tubular left auricle with pectinate muscles projects forward."],"structural_adaptations":["Thin-walled, because it fills the ventricle at low pressure."],"functions":["Receives oxygenated blood from the lungs via the pulmonary veins.","Passes blood to the left ventricle through the mitral valve."],"blood_supply":"Branches of the left coronary artery (mainly the circumflex branch).","clinical_relevance":["The left atrial appendage is a common site of thrombus formation in atrial fibrillation, increasing stroke risk.","Mitral valve disease can enlarge the left atrium."],"related_structures":["left-ventricle","mitral-valve","pulmonary-veins"],"difficulty_level":"beginner"},{"system_id":"cardiovascular","region_id":"thorax","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Standard textbook; this entry is an original educational summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)"}],"id":"left-ventricle","anatomical_name":"Left ventricle","common_name":"Left lower chamber of the heart","synonyms":["ventriculus sinister","LV"],"organ_id":"heart","classification":"Heart chamber (pumping chamber, systemic circuit)","location":"Forms the apex, the left border and most of the diaphragmatic surface of the heart.","external_characteristics":["The apex of the heart is formed by the left ventricle and lies in the left fifth intercostal space in the midclavicular line."],"internal_characteristics":["Thick myocardium with fine trabeculae carneae.","Two large papillary muscles attach via chordae tendineae to the mitral valve cusps.","A smooth-walled aortic vestibule leads to the aortic valve."],"structural_adaptations":["The wall is typically about three times as thick as the right ventricle, because it must generate the high pressure needed to drive blood around the systemic circulation.","A circular cross-section lets it contract efficiently and generate high pressure."],"functions":["Receives oxygenated blood from the left atrium.","Pumps blood through the aortic valve into the aorta for the systemic circulation."],"blood_supply":"Left coronary artery (anterior interventricular and circumflex branches) and the right coronary artery (posterior interventricular artery in right-dominant hearts).","clinical_relevance":["The commonest site of myocardial infarction.","Chronic hypertension or aortic stenosis can cause left ventricular hypertrophy."],"related_structures":["left-atrium","mitral-valve","aortic-valve","aorta","cardiac-muscle","coronary-arteries"],"difficulty_level":"beginner"},{"system_id":"cardiovascular","region_id":"thorax","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Standard textbook; this entry is an original educational summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)"}],"id":"tricuspid-valve","anatomical_name":"Tricuspid valve","common_name":"Right atrioventricular valve","synonyms":["right AV valve","valva atrioventricularis dextra"],"organ_id":"heart","classification":"Atrioventricular valve","location":"Between the right atrium and right ventricle.","internal_characteristics":["Three cusps (anterior, posterior and septal).","Cusps are anchored by chordae tendineae to papillary muscles."],"structural_adaptations":["Chordae tendineae and papillary muscles stop the cusps from everting into the atrium when the ventricle contracts."],"functions":["Allows blood to flow from right atrium to right ventricle.","Closes during ventricular systole to prevent backflow into the right atrium."],"clinical_relevance":["Tricuspid regurgitation allows blood to flow back into the right atrium and can raise systemic venous pressure."],"related_structures":["right-atrium","right-ventricle"],"difficulty_level":"intermediate"},{"system_id":"cardiovascular","region_id":"thorax","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Standard textbook; this entry is an original educational summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)"}],"id":"mitral-valve","anatomical_name":"Mitral valve","common_name":"Left atrioventricular valve","synonyms":["bicuspid valve","left AV valve"],"organ_id":"heart","classification":"Atrioventricular valve","location":"Between the left atrium and left ventricle.","internal_characteristics":["Two cusps (anterior and posterior).","Anchored by chordae tendineae to two papillary muscles."],"structural_adaptations":["Its strong chordal attachments allow the valve to stay closed against high left ventricular pressure."],"functions":["Allows blood to flow from left atrium to left ventricle.","Closes in ventricular systole to prevent backflow into the left atrium."],"clinical_relevance":["Mitral stenosis and regurgitation are common valve diseases; mitral valve prolapse is a frequent finding."],"related_structures":["left-atrium","left-ventricle"],"difficulty_level":"intermediate"},{"system_id":"cardiovascular","region_id":"thorax","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Standard textbook; this entry is an original educational summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)"}],"id":"aortic-valve","anatomical_name":"Aortic valve","common_name":"Valve between left ventricle and aorta","synonyms":["aortic semilunar valve"],"organ_id":"heart","classification":"Semilunar valve","location":"At the junction between the left ventricular outflow tract and the ascending aorta.","internal_characteristics":["Three semilunar cusps (right, left and posterior/non-coronary).","Behind each cusp is an aortic sinus; the right and left coronary arteries arise from the right and left sinuses."],"structural_adaptations":["Pocket-shaped cusps fill with blood during diastole and meet in the middle to seal the outlet; no chordae are needed."],"functions":["Opens during ventricular systole to eject blood into the aorta.","Closes in diastole to prevent backflow into the left ventricle."],"clinical_relevance":["Aortic stenosis obstructs outflow and can lead to left ventricular hypertrophy.","Aortic regurgitation causes backflow in diastole."],"related_structures":["left-ventricle","aorta","coronary-arteries"],"difficulty_level":"intermediate"},{"system_id":"cardiovascular","region_id":"thorax","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Standard textbook; this entry is an original educational summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)"}],"id":"pulmonary-valve","anatomical_name":"Pulmonary valve","common_name":"Valve between right ventricle and pulmonary trunk","synonyms":["pulmonary semilunar valve"],"organ_id":"heart","classification":"Semilunar valve","location":"At the apex of the conus arteriosus, where the right ventricle meets the pulmonary trunk.","internal_characteristics":["Three semilunar cusps (anterior, right and left)."],"structural_adaptations":["Pocket-shaped cusps close passively when blood tries to flow back."],"functions":["Opens in ventricular systole to eject blood into the pulmonary trunk.","Closes in diastole to prevent backflow into the right ventricle."],"clinical_relevance":["Pulmonary stenosis is a common congenital valve defect."],"related_structures":["right-ventricle","pulmonary-trunk"],"difficulty_level":"intermediate"},{"system_id":"cardiovascular","region_id":"thorax","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Standard textbook; this entry is an original educational summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)"}],"id":"sinoatrial-node","anatomical_name":"Sinoatrial node","common_name":"SA node, natural pacemaker","synonyms":["SAN","sinus node"],"organ_id":"heart","classification":"Cardiac conducting tissue","location":"In the wall of the right atrium near the opening of the superior vena cava, at the upper end of the crista terminalis.","internal_characteristics":["Cluster of specialised cardiac muscle cells that depolarise spontaneously."],"structural_adaptations":["Cells have an unstable resting membrane potential (pacemaker potential) so they reach threshold on their own, faster than other cardiac cells."],"functions":["Initiates the cardiac impulse in normal sinus rhythm.","Rate is modulated by sympathetic (increase) and parasympathetic (decrease) input."],"blood_supply":"Usually the sinoatrial nodal branch of the right coronary artery (in a majority of people).","nerve_supply":"Sympathetic and parasympathetic (vagus) fibres via the cardiac plexus.","clinical_relevance":["Sinus node dysfunction may cause slow heart rates and can be treated with a pacemaker."],"related_structures":["right-atrium","cardiac-muscle"],"difficulty_level":"advanced"},{"system_id":"cardiovascular","region_id":"thorax","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Standard textbook; this entry is an original educational summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)"}],"id":"cardiac-muscle","anatomical_name":"Cardiac muscle (myocardium)","common_name":"Heart muscle","synonyms":["myocardium","musculus cardiacus"],"organ_id":"heart","classification":"Muscle tissue (striated, involuntary)","location":"The middle layer of the heart wall, between the endocardium and epicardium.","internal_characteristics":["Short, branching cells with one or two central nuclei.","Cross-striations due to sarcomeres.","Intercalated discs join cells end to end."],"structural_adaptations":["Intercalated discs contain desmosomes (mechanical strength) and gap junctions (rapid electrical spread), so the myocardium acts as a functional syncytium.","Abundant mitochondria support continuous aerobic work."],"functions":["Contracts rhythmically to pump blood."],"blood_supply":"Coronary arteries.","clinical_relevance":["Myocardial infarction causes ischaemic necrosis of cardiac muscle; cardiac muscle has very limited regenerative capacity."],"related_structures":["left-ventricle","coronary-arteries"],"difficulty_level":"intermediate"},{"system_id":"cardiovascular","region_id":"thorax","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Standard textbook; this entry is an original educational summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)"}],"id":"coronary-arteries","anatomical_name":"Coronary arteries","common_name":"Arteries of the heart","synonyms":["arteriae coronariae","right and left coronary arteries"],"organ_id":"heart","classification":"Arteries (muscular)","location":"Arise from the right and left aortic sinuses and run in the coronary (atrioventricular) and interventricular grooves.","internal_characteristics":["The left coronary artery divides into the anterior interventricular (LAD) and circumflex arteries.","The right coronary artery gives rise to the marginal branch and in most people the posterior interventricular artery."],"structural_adaptations":["Most coronary flow to the left ventricle occurs in diastole, when the myocardium is relaxed and aortic recoil maintains pressure."],"functions":["Supply oxygenated blood to the myocardium."],"clinical_relevance":["Atherosclerosis of the coronary arteries causes coronary artery disease, angina and myocardial infarction."],"related_structures":["aorta","aortic-valve","cardiac-muscle","left-ventricle"],"difficulty_level":"intermediate"},{"system_id":"cardiovascular","region_id":"thorax","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Standard textbook; this entry is an original educational summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)"}],"id":"aorta","anatomical_name":"Aorta","common_name":"Main artery of the body","synonyms":["aorta ascendens","ascending aorta"],"organ_id":"great-vessels","classification":"Elastic artery","location":"Arises from the left ventricle; ascends, arches over the left main bronchus, then descends through the thorax and abdomen.","internal_characteristics":["Parts: ascending aorta, aortic arch, descending thoracic aorta, abdominal aorta.","The arch gives off the brachiocephalic trunk, left common carotid and left subclavian arteries."],"structural_adaptations":["The tunica media contains many elastic lamellae. The wall stretches during systole and recoils in diastole (Windkessel effect), converting pulsatile ejection into smoother flow."],"functions":["Distributes oxygenated blood from the left ventricle to the systemic arteries."],"clinical_relevance":["Aortic aneurysm and dissection are life-threatening conditions.","Coarctation of the aorta is a congenital narrowing."],"related_structures":["left-ventricle","aortic-valve","coronary-arteries"],"difficulty_level":"beginner"},{"system_id":"cardiovascular","region_id":"thorax","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Standard textbook; this entry is an original educational summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)"}],"id":"pulmonary-trunk","anatomical_name":"Pulmonary trunk","common_name":"Main pulmonary artery","synonyms":["truncus pulmonalis"],"organ_id":"great-vessels","classification":"Elastic artery","location":"Arises from the right ventricle and passes upward and backward, dividing into the right and left pulmonary arteries.","structural_adaptations":["Thinner-walled than the aorta, because it carries blood at much lower pressure."],"functions":["Carries deoxygenated blood from the right ventricle to the lungs."],"clinical_relevance":["Pulmonary embolism occurs when a thrombus, most often from the deep veins of the legs, lodges in the pulmonary arterial tree."],"related_structures":["right-ventricle","pulmonary-valve","pulmonary-veins"],"difficulty_level":"beginner"},{"system_id":"cardiovascular","region_id":"thorax","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Standard textbook; this entry is an original educational summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)"}],"id":"superior-vena-cava","anatomical_name":"Superior vena cava","common_name":"Upper main vein","synonyms":["SVC"],"organ_id":"great-vessels","classification":"Large vein","location":"Formed by the union of the right and left brachiocephalic veins behind the first right costal cartilage; descends to enter the right atrium.","functions":["Returns deoxygenated blood from the head, neck, upper limbs and thoracic wall to the right atrium."],"clinical_relevance":["SVC obstruction (for example by a mediastinal tumour) causes swelling of the face and arms."],"related_structures":["right-atrium","inferior-vena-cava"],"difficulty_level":"beginner"},{"system_id":"cardiovascular","region_id":"thorax","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Standard textbook; this entry is an original educational summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)"}],"id":"inferior-vena-cava","anatomical_name":"Inferior vena cava","common_name":"Lower main vein","synonyms":["IVC"],"organ_id":"great-vessels","classification":"Large vein","location":"Ascends along the right side of the vertebral column through the abdomen, pierces the diaphragm at T8 and enters the right atrium.","functions":["Returns deoxygenated blood from the lower limbs, pelvis and abdomen to the right atrium."],"clinical_relevance":["Pulmonary emboli often originate in the deep leg veins that drain via the IVC."],"related_structures":["right-atrium","superior-vena-cava"],"difficulty_level":"beginner"},{"system_id":"cardiovascular","region_id":"thorax","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Standard textbook; this entry is an original educational summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)"}],"id":"pulmonary-veins","anatomical_name":"Pulmonary veins","common_name":"Veins from the lungs to the heart","synonyms":["venae pulmonales"],"organ_id":"great-vessels","classification":"Veins (exception: carry oxygenated blood)","location":"Typically four veins (two from each lung) that enter the posterior wall of the left atrium.","functions":["Return oxygenated blood from the lungs to the left atrium."],"clinical_relevance":["Ectopic electrical activity originating in the pulmonary veins can trigger atrial fibrillation."],"related_structures":["left-atrium","pulmonary-trunk"],"difficulty_level":"intermediate"},{"system_id":"skeletal","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Standard textbook; this entry is an original educational summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)"}],"id":"skull","anatomical_name":"Skull","common_name":"Skull","synonyms":["cranium and facial skeleton"],"region_id":"head","organ_id":"skull-unit","classification":"Irregular and flat bones (axial skeleton)","location":"Skeleton of the head, resting on the atlas (C1) at the atlanto-occipital joints.","internal_characteristics":["The neurocranium encloses the brain; the viscerocranium forms the face.","Most skull bones are joined by fibrous sutures; the mandible is the only bone that moves at a synovial joint (the temporomandibular joint).","Flat cranial bones have two compact plates (tables) separated by spongy diploe."],"structural_adaptations":["The diploe reduces weight while keeping rigidity.","Sutures allow growth during childhood and then largely fuse in adulthood."],"functions":["Protects the brain and special sense organs.","Provides attachment for muscles of mastication and facial expression.","Houses openings (foramina) for cranial nerves and vessels."],"articulations":["Atlas (C1) at the atlanto-occipital joints","Mandible at the temporomandibular joints"],"clinical_relevance":["Skull fractures near the pterion may damage the middle meningeal artery and cause extradural haematoma."],"related_structures":["vertebral-column"],"difficulty_level":"beginner"},{"system_id":"skeletal","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Standard textbook; this entry is an original educational summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)"}],"id":"vertebral-column","anatomical_name":"Vertebral column","common_name":"Spine, backbone","synonyms":["columna vertebralis","spinal column"],"region_id":"back","organ_id":"vertebral-column-unit","classification":"Irregular bones (axial skeleton)","location":"Midline of the back, extending from the skull to the coccyx.","internal_characteristics":["Typically 33 vertebrae: 7 cervical, 12 thoracic, 5 lumbar, 5 fused sacral and 4 (variable) coccygeal.","Intervertebral discs (annulus fibrosus and nucleus pulposus) lie between adjacent vertebral bodies.","Four curvatures: cervical and lumbar lordoses, thoracic and sacral kyphoses."],"structural_adaptations":["Vertebral bodies enlarge from cervical to lumbar regions as they bear progressively more weight.","The curvatures increase shock absorption and resilience.","Stacked vertebrae form a vertebral canal that protects the spinal cord."],"functions":["Supports the trunk and transmits weight to the pelvis.","Protects the spinal cord and emerging spinal nerves.","Allows flexion, extension, lateral flexion and rotation."],"articulations":["Intervertebral discs and facet (zygapophysial) joints","Skull at the atlanto-occipital joint","Ribs at the costovertebral joints (thoracic region)","Sacrum with the hip bones at the sacro-iliac joints"],"clinical_relevance":["Posterolateral herniation of an intervertebral disc can compress a spinal nerve root.","Abnormal curvatures include scoliosis, excessive kyphosis and excessive lordosis."],"related_structures":["skull","rib-cage","pelvis"],"difficulty_level":"beginner"},{"system_id":"skeletal","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Standard textbook; this entry is an original educational summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)"}],"id":"rib-cage","anatomical_name":"Rib cage (thoracic cage)","common_name":"Ribs","synonyms":["costae","thoracic cage"],"region_id":"thorax","organ_id":"thoracic-cage-unit","classification":"Flat bones with costal cartilages (axial skeleton)","location":"Encloses the thoracic cavity.","internal_characteristics":["12 pairs of ribs: 7 true (vertebrosternal), 3 false (vertebrochondral) and 2 floating (vertebral) ribs.","Costal cartilages connect ribs 1-10 to the sternum directly or indirectly."],"structural_adaptations":["Costal cartilages give the cage elasticity, allowing it to expand during breathing.","Ribs are angled downwards so that elevation increases the transverse and antero-posterior thoracic dimensions."],"functions":["Protects the heart, lungs and great vessels.","Provides attachment for respiratory and upper-limb muscles.","Changes thoracic volume during ventilation."],"articulations":["Thoracic vertebrae at costovertebral joints","Sternum via costal cartilages (sternocostal joints)"],"clinical_relevance":["Rib fractures are most common in ribs 5-9; the 1st-3rd are well protected and fracture only with major force."],"related_structures":["sternum","vertebral-column"],"difficulty_level":"beginner"},{"system_id":"skeletal","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Standard textbook; this entry is an original educational summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)"}],"id":"sternum","anatomical_name":"Sternum","common_name":"Breastbone","synonyms":["breastbone"],"region_id":"thorax","organ_id":"thoracic-cage-unit","classification":"Flat bone (axial skeleton)","location":"Anterior midline of the thorax.","internal_characteristics":["Three parts: manubrium, body and xiphoid process.","The manubriosternal joint forms the palpable sternal angle at the level of the 2nd costal cartilage."],"structural_adaptations":["Contains red bone marrow in adults, which is accessible for marrow aspiration."],"functions":["Anchors the costal cartilages and protects the mediastinal organs."],"articulations":["Clavicles (sternoclavicular joints)","Costal cartilages 1-7"],"clinical_relevance":["The sternal angle is a landmark for counting ribs and marks the level of the T4/T5 intervertebral disc."],"related_structures":["rib-cage","clavicle"],"difficulty_level":"beginner"},{"system_id":"skeletal","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Standard textbook; this entry is an original educational summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)"}],"id":"clavicle","anatomical_name":"Clavicle","common_name":"Collarbone","synonyms":["collar bone"],"region_id":"upper-limb","organ_id":"pectoral-girdle-unit","classification":"Long bone (appendicular skeleton)","location":"Horizontal S-shaped bone between the sternum and the scapula.","internal_characteristics":["Medial end is convex forward; lateral end is concave forward.","It has no medullary cavity."],"structural_adaptations":["Acts as a strut that holds the upper limb away from the trunk, allowing a wide range of arm movement."],"functions":["Transmits forces from the upper limb to the axial skeleton.","Protects underlying neurovascular structures."],"articulations":["Sternum (sternoclavicular joint)","Acromion of the scapula (acromioclavicular joint)"],"clinical_relevance":["The clavicle is the most commonly fractured bone in children and young adults, typically at the junction of the middle and lateral thirds."],"related_structures":["scapula","sternum","humerus"],"difficulty_level":"beginner"},{"system_id":"skeletal","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Standard textbook; this entry is an original educational summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)"}],"id":"scapula","anatomical_name":"Scapula","common_name":"Shoulder blade","synonyms":["shoulder blade"],"region_id":"upper-limb","organ_id":"pectoral-girdle-unit","classification":"Flat bone (appendicular skeleton)","location":"Posterolateral thorax, overlying ribs 2-7.","internal_characteristics":["Landmarks: spine, acromion, coracoid process, glenoid cavity, superior, medial and lateral borders."],"structural_adaptations":["The shallow glenoid cavity allows great mobility at the shoulder at the cost of stability.","The spine and processes serve as levers for attached muscles."],"functions":["Provides the socket for the humeral head.","Gives attachment to many shoulder muscles and the rotator cuff."],"articulations":["Humerus (glenohumeral joint)","Clavicle (acromioclavicular joint)"],"clinical_relevance":["The shoulder is the most commonly dislocated major joint, typically anteriorly-inferiorly."],"related_structures":["clavicle","humerus"],"difficulty_level":"intermediate"},{"system_id":"skeletal","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Standard textbook; this entry is an original educational summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)"}],"id":"humerus","anatomical_name":"Humerus","common_name":"Upper arm bone","synonyms":["arm bone"],"region_id":"upper-limb","organ_id":"pectoral-girdle-unit","classification":"Long bone (appendicular skeleton)","location":"The skeleton of the arm, between the shoulder and elbow.","internal_characteristics":["Proximal end: head, anatomical neck, surgical neck, greater and lesser tubercles.","Shaft: deltoid tuberosity and radial groove.","Distal end: capitulum, trochlea and epicondyles."],"structural_adaptations":["The rounded head fits the glenoid cavity, permitting multi-axial movement.","The thick compact shaft resists bending and torsion."],"functions":["Lever for muscles that move the shoulder and elbow."],"articulations":["Scapula (glenohumeral joint)","Radius and ulna (elbow joint)"],"clinical_relevance":["A fracture of the surgical neck can injure the axillary nerve; a mid-shaft fracture can injure the radial nerve."],"related_structures":["scapula","radius","ulna"],"difficulty_level":"intermediate"},{"system_id":"skeletal","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Standard textbook; this entry is an original educational summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)"}],"id":"radius","anatomical_name":"Radius","common_name":"Lateral forearm bone","synonyms":[],"region_id":"upper-limb","organ_id":"pectoral-girdle-unit","classification":"Long bone (appendicular skeleton)","location":"Lateral (thumb side) bone of the forearm in the anatomical position.","internal_characteristics":["Small head proximally; broad distal end with the styloid process."],"structural_adaptations":["Rotates around the ulna during pronation and supination.","The distal end is wider than the ulna and bears most of the load from the hand."],"functions":["Transmits force from the hand to the arm; allows forearm rotation."],"articulations":["Humerus (capitulum)","Ulna (proximal and distal radio-ulnar joints)","Carpal bones (wrist joint)"],"clinical_relevance":["A Colles fracture is a fracture of the distal radius with dorsal displacement, commonly after a fall onto an outstretched hand."],"related_structures":["ulna","humerus"],"difficulty_level":"intermediate"},{"system_id":"skeletal","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Standard textbook; this entry is an original educational summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)"}],"id":"ulna","anatomical_name":"Ulna","common_name":"Medial forearm bone","synonyms":[],"region_id":"upper-limb","organ_id":"pectoral-girdle-unit","classification":"Long bone (appendicular skeleton)","location":"Medial (little finger side) bone of the forearm in the anatomical position.","internal_characteristics":["Proximal end has the olecranon and coronoid process, forming the trochlear notch."],"structural_adaptations":["The trochlear notch grips the humeral trochlea, forming a stable hinge."],"functions":["Forms the main part of the elbow joint; acts as the stable axis for rotation of the radius."],"articulations":["Humerus (elbow joint)","Radius (radio-ulnar joints)"],"clinical_relevance":["The ulnar nerve passes behind the medial epicondyle of the humerus and is vulnerable there."],"related_structures":["radius","humerus"],"difficulty_level":"intermediate"},{"system_id":"skeletal","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Standard textbook; this entry is an original educational summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)"}],"id":"pelvis","anatomical_name":"Pelvis (hip bones and sacrum)","common_name":"Pelvic girdle","synonyms":["os coxae","hip bone"],"region_id":"pelvis","organ_id":"pelvic-girdle-unit","classification":"Irregular bones (appendicular skeleton with sacrum)","location":"Base of the trunk, connecting the vertebral column to the lower limbs.","internal_characteristics":["Each hip bone is formed by the ilium, ischium and pubis, fused at the acetabulum.","The two hip bones meet at the pubic symphysis and articulate with the sacrum posteriorly."],"structural_adaptations":["Strong, thick bones and robust ligaments transmit body weight to the lower limbs.","The female pelvis is generally wider with a larger pelvic inlet and outlet, an adaptation for childbirth."],"functions":["Supports the weight of the upper body.","Protects the pelvic viscera.","Provides attachment for the muscles of the trunk and lower limb."],"articulations":["Sacrum (sacro-iliac joints)","Femur (hip joint)","Contralateral hip bone (pubic symphysis)"],"clinical_relevance":["Pelvic fractures can cause major haemorrhage and injury to pelvic organs."],"related_structures":["femur","vertebral-column"],"difficulty_level":"intermediate"},{"system_id":"skeletal","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Standard textbook; this entry is an original educational summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)"}],"id":"femur","anatomical_name":"Femur","common_name":"Thigh bone","synonyms":["thigh bone"],"region_id":"lower-limb","organ_id":"pelvic-girdle-unit","classification":"Long bone (appendicular skeleton)","location":"The skeleton of the thigh.","internal_characteristics":["Proximal end: head, neck, greater and lesser trochanters.","Distal end: medial and lateral condyles.","The shaft has a roughened posterior ridge, the linea aspera."],"structural_adaptations":["The neck-shaft angle of roughly 125 degrees places the shaft under the body, helping weight transmission.","It is the longest and strongest bone in the body."],"functions":["Supports body weight.","Lever for hip and knee movements."],"articulations":["Acetabulum (hip joint)","Tibia and patella (knee joint)"],"blood_supply":"The femoral head receives blood largely via the medial and lateral circumflex femoral arteries.","clinical_relevance":["Fractures of the femoral neck can disrupt the blood supply to the head and lead to avascular necrosis, particularly in older adults."],"related_structures":["pelvis","patella","tibia"],"difficulty_level":"beginner"},{"system_id":"skeletal","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Standard textbook; this entry is an original educational summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)"}],"id":"patella","anatomical_name":"Patella","common_name":"Kneecap","synonyms":["kneecap"],"region_id":"lower-limb","organ_id":"pelvic-girdle-unit","classification":"Sesamoid bone","location":"Within the quadriceps femoris tendon, in front of the knee joint.","structural_adaptations":["Increases the leverage of the quadriceps by moving the line of pull away from the knee joint axis.","Its posterior surface is covered by thick articular cartilage."],"functions":["Protects the front of the knee; improves quadriceps efficiency in extending the knee."],"articulations":["Femur (patellofemoral joint)"],"clinical_relevance":["Patellar dislocation is usually lateral; patellofemoral pain syndrome is common."],"related_structures":["femur","tibia"],"difficulty_level":"beginner"},{"system_id":"skeletal","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Standard textbook; this entry is an original educational summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)"}],"id":"tibia","anatomical_name":"Tibia","common_name":"Shin bone","synonyms":["shinbone"],"region_id":"lower-limb","organ_id":"pelvic-girdle-unit","classification":"Long bone (appendicular skeleton)","location":"Medial and larger bone of the leg.","internal_characteristics":["Proximal end: medial and lateral condyles and the tibial tuberosity.","Distal end: medial malleolus.","The anterior border is subcutaneous."],"structural_adaptations":["It is the main weight-bearing bone of the leg; the broad proximal end spreads the load received from the femur."],"functions":["Transmits body weight from the femur to the foot."],"articulations":["Femur (knee joint)","Fibula (tibiofibular joints)","Talus (ankle joint)"],"clinical_relevance":["The subcutaneous anterior border makes the tibia prone to open fractures."],"related_structures":["femur","fibula","patella"],"difficulty_level":"beginner"},{"system_id":"skeletal","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Standard textbook; this entry is an original educational summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)"}],"id":"fibula","anatomical_name":"Fibula","common_name":"Calf bone","synonyms":[],"region_id":"lower-limb","organ_id":"pelvic-girdle-unit","classification":"Long bone (appendicular skeleton)","location":"Lateral, slender bone of the leg.","internal_characteristics":["Head proximally; lateral malleolus distally."],"structural_adaptations":["Not a weight-bearing bone; it is slender and serves mainly for muscle attachment and ankle stability."],"functions":["Provides attachment for muscles; the lateral malleolus stabilises the ankle joint."],"articulations":["Tibia (tibiofibular joints)","Talus (ankle joint)"],"clinical_relevance":["The common fibular nerve winds around the neck of the fibula and can be injured by fractures here."],"related_structures":["tibia"],"difficulty_level":"intermediate"}]$j$::jsonb) on conflict do nothing;
insert into public.lessons ("id", "title", "subject", "system_id", "region_id", "organ_id", "difficulty", "summary", "learning_objectives", "related_structure_ids", "exercises", "bundle_id", "references") select "id", "title", "subject", "system_id", "region_id", "organ_id", "difficulty", "summary", "learning_objectives", "related_structure_ids", "exercises", "bundle_id", "references" from jsonb_populate_recordset(null::public.lessons, $j$[{"id":"heart-overview","title":"The heart: chambers, surfaces and circulation","subject":"anatomy","system_id":"cardiovascular","region_id":"thorax","organ_id":"heart","difficulty":"beginner","summary":"The four chambers of the heart, how blood passes through them and how the heart sits in the thorax.","learning_objectives":["Name the four chambers and what each receives and pumps.","Describe the position and surfaces of the heart.","Trace blood through the pulmonary and systemic circulations."],"related_structure_ids":["right-atrium","right-ventricle","left-atrium","left-ventricle","aorta","pulmonary-trunk"],"exercises":[{"question":"Which chamber forms the apex of the heart?","answer":"The left ventricle."},{"question":"Which vessels enter the left atrium?","answer":"The pulmonary veins (normally four)."},{"question":"Name the three layers of the heart wall.","answer":"Endocardium, myocardium and epicardium."}],"bundle_id":"heart","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Further reading; notes here are an original summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)"}]},{"id":"heart-valves","title":"Heart valves and the conducting system","subject":"anatomy","system_id":"cardiovascular","region_id":"thorax","organ_id":"heart","difficulty":"intermediate","summary":"Atrioventricular and semilunar valves, how they close, and how the heartbeat is initiated and conducted.","learning_objectives":["Distinguish atrioventricular from semilunar valves.","Explain the role of chordae tendineae and papillary muscles.","Trace the conduction pathway from the SA node."],"related_structure_ids":["tricuspid-valve","mitral-valve","aortic-valve","pulmonary-valve","sinoatrial-node"],"exercises":[{"question":"Why do the semilunar valves not need chordae tendineae?","answer":"Their pocket-shaped cusps are closed by back-pressure of blood and are not pushed back by a contracting chamber wall."},{"question":"Why is conduction delayed at the AV node?","answer":"It lets atrial contraction finish filling the ventricles before ventricular contraction begins."}],"bundle_id":"heart","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Further reading; notes here are an original summary."},{"title":"Guyton and Hall Textbook of Medical Physiology","source":"Hall & Hall (Elsevier)"}]},{"id":"great-vessels-circulation","title":"Great vessels and the two circulations","subject":"physiology","system_id":"cardiovascular","region_id":"thorax","organ_id":"great-vessels","difficulty":"beginner","summary":"The vessels attached to the heart and the pulmonary and systemic circuits.","learning_objectives":["Name the great vessels and their connections.","Compare the pulmonary and systemic circulations.","Explain why pulmonary veins carry oxygenated blood."],"related_structure_ids":["aorta","pulmonary-trunk","superior-vena-cava","inferior-vena-cava","pulmonary-veins"],"exercises":[{"question":"Why are pulmonary veins an exception to the idea that veins carry deoxygenated blood?","answer":"Veins are defined by direction of flow (towards the heart). Pulmonary veins return blood from the lungs, which has just been oxygenated."}],"bundle_id":"heart","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Further reading; notes here are an original summary."},{"title":"Guyton and Hall Textbook of Medical Physiology","source":"Hall & Hall (Elsevier)"}]},{"id":"cardiac-cycle","title":"The cardiac cycle","subject":"physiology","system_id":"cardiovascular","region_id":"thorax","organ_id":"heart","difficulty":"intermediate","summary":"Phases of systole and diastole, valve behaviour and blood flow through the heart.","learning_objectives":["Describe the phases of the cardiac cycle.","State when each valve opens and closes.","Define stroke volume, heart rate and cardiac output."],"related_structure_ids":["left-ventricle","right-ventricle","mitral-valve","aortic-valve"],"exercises":[{"question":"During which phase are all four heart valves closed?","answer":"Isovolumetric contraction and isovolumetric relaxation."},{"question":"What is cardiac output if stroke volume is 70 mL and heart rate is 70 beats per minute?","answer":"70 × 70 = 4900 mL per minute (about 4.9 L/min)."}],"bundle_id":"heart","references":[{"title":"Guyton and Hall Textbook of Medical Physiology","source":"Hall & Hall (Elsevier)"}]},{"id":"bone-classification","title":"Bone classification and the structure of a long bone","subject":"anatomy","system_id":"skeletal","difficulty":"beginner","summary":"Shapes of bones and the parts of a typical long bone.","learning_objectives":["Classify bones by shape with an example of each.","Name the parts of a long bone.","Relate bone structure to function."],"related_structure_ids":["humerus","femur","patella","rib-cage"],"exercises":[{"question":"What is a sesamoid bone?","answer":"A bone that develops within a tendon; the patella is the largest example."},{"question":"Which part of a long bone is the shaft?","answer":"The diaphysis."}],"bundle_id":"skeleton","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Further reading; notes here are an original summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)"}]},{"id":"axial-skeleton","title":"The axial skeleton","subject":"anatomy","system_id":"skeletal","region_id":"back","difficulty":"beginner","summary":"The skull, vertebral column and thoracic cage.","learning_objectives":["List the regions of the vertebral column and their vertebra counts.","Name the types of ribs.","Describe the parts of the sternum."],"related_structure_ids":["skull","vertebral-column","rib-cage","sternum"],"exercises":[{"question":"How many cervical vertebrae are there?","answer":"Seven."},{"question":"Which ribs are floating ribs?","answer":"Ribs 11 and 12 (they do not attach to the sternum or to a costal cartilage of another rib)."}],"bundle_id":"skeleton","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Further reading; notes here are an original summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)"}]},{"id":"upper-limb-bones","title":"Bones of the upper limb","subject":"anatomy","system_id":"skeletal","region_id":"upper-limb","difficulty":"intermediate","summary":"Pectoral girdle, arm and forearm bones and their joints.","learning_objectives":["Name the bones of the pectoral girdle and upper limb.","Identify the articulations at the shoulder and elbow.","Describe the clinically important features of the clavicle, humerus and distal radius."],"related_structure_ids":["clavicle","scapula","humerus","radius","ulna"],"exercises":[{"question":"Which forearm bone is lateral in the anatomical position?","answer":"The radius."},{"question":"Which nerve is at risk in a fracture of the surgical neck of the humerus?","answer":"The axillary nerve."}],"bundle_id":"skeleton","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Further reading; notes here are an original summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)"}]},{"id":"lower-limb-bones","title":"Bones of the pelvis and lower limb","subject":"anatomy","system_id":"skeletal","region_id":"lower-limb","difficulty":"intermediate","summary":"Hip bone, femur, patella, tibia and fibula.","learning_objectives":["Name the three parts of the hip bone.","Name the main parts of the femur.","State the weight-bearing bone of the leg."],"related_structure_ids":["pelvis","femur","patella","tibia","fibula"],"exercises":[{"question":"Which bone of the leg bears most of the body weight?","answer":"The tibia."}],"bundle_id":"skeleton","references":[{"title":"Gray's Anatomy for Students","source":"Drake, Vogl & Mitchell (Elsevier)","note":"Further reading; notes here are an original summary."},{"title":"Clinically Oriented Anatomy","source":"Moore, Dalley & Agur (Wolters Kluwer)"}]},{"id":"bone-histology","title":"Bone tissue and cardiac muscle: histology essentials","subject":"histology","system_id":"skeletal","difficulty":"intermediate","summary":"Compact bone (osteons) and cardiac muscle: what you see and why.","learning_objectives":["Identify an osteon and name its parts.","Describe the features of cardiac muscle in longitudinal section."],"related_structure_ids":["cardiac-muscle","femur"],"exercises":[{"question":"What lies in the centre of an osteon?","answer":"The central (Haversian) canal containing blood vessels and nerves."},{"question":"What junctions in intercalated discs allow electrical coupling?","answer":"Gap junctions."}],"references":[{"title":"Histology: A Text and Atlas","source":"Pawlina (Wolters Kluwer)"}]},{"id":"embryo-early","title":"Fertilisation to the three germ layers","subject":"embryology","system_id":"reproductive","difficulty":"beginner","summary":"Fertilisation, cleavage, implantation and gastrulation.","learning_objectives":["Describe where fertilisation usually occurs.","Name the three germ layers and one derivative of each.","Define gastrulation."],"related_structure_ids":[],"exercises":[{"question":"What is gastrulation?","answer":"The process that forms the three germ layers (ectoderm, mesoderm and endoderm) from the epiblast in week 3."}],"references":[{"title":"Langman's Medical Embryology","source":"Sadler (Wolters Kluwer)"}]},{"id":"embryo-heart","title":"Development of the heart","subject":"embryology","system_id":"cardiovascular","region_id":"thorax","organ_id":"heart","difficulty":"advanced","summary":"From the cardiac tube to a four-chambered heart.","learning_objectives":["Describe the origin of the primitive heart tube.","Explain heart tube looping.","Name the septa that divide the heart."],"related_structure_ids":["right-atrium","left-ventricle"],"exercises":[{"question":"Which embryonic tissue gives rise to the heart tube?","answer":"Splanchnic (lateral plate) mesoderm of the cardiogenic area."}],"references":[{"title":"Langman's Medical Embryology","source":"Sadler (Wolters Kluwer)"}]},{"id":"embryo-fetal-circulation","title":"Fetal circulation","subject":"embryology","system_id":"cardiovascular","region_id":"thorax","organ_id":"heart","difficulty":"intermediate","summary":"Shunts that bypass the fetal lungs and liver, and how they change at birth.","learning_objectives":["Name the three fetal shunts.","Explain why the foramen ovale and ductus arteriosus are needed.","State what each becomes after birth."],"related_structure_ids":["right-atrium","left-atrium","pulmonary-trunk","aorta"],"exercises":[{"question":"What does the foramen ovale become in the adult?","answer":"The fossa ovalis in the interatrial septum."}],"references":[{"title":"Langman's Medical Embryology","source":"Sadler (Wolters Kluwer)"}]}]$j$::jsonb) on conflict do nothing;
insert into public.lesson_sections ("lesson_id", "sort_order", "heading", "body", "kind") select "lesson_id", "sort_order", "heading", "body", "kind" from jsonb_populate_recordset(null::public.lesson_sections, $j$[{"lesson_id":"heart-overview","sort_order":0,"heading":"Position and coverings","body":["The heart lies in the middle mediastinum, with about two thirds of its mass to the left of the midline. It is enclosed in the pericardium: a tough outer fibrous layer and an inner serous sac with parietal and visceral (epicardial) layers separated by a thin film of pericardial fluid.","The heart wall has three layers: epicardium (outer), myocardium (middle muscle) and endocardium (inner lining)."],"kind":"text"},{"lesson_id":"heart-overview","sort_order":1,"heading":"Characteristics of the chambers","body":["Right atrium: receives the superior and inferior vena cavae and coronary sinus; has a rough anterior wall (pectinate muscles) and a smooth posterior part.","Right ventricle: forms most of the anterior surface; internal trabeculae carneae and papillary muscles; outflow part leads to the pulmonary trunk.","Left atrium: forms most of the base (posterior surface); receives the pulmonary veins.","Left ventricle: forms the apex and left border; thick, smooth-walled outflow part leads to the aorta."],"kind":"characteristics"},{"lesson_id":"heart-overview","sort_order":2,"heading":"Adaptations","body":["Atria have thin walls because they move blood only a short distance into the ventricles at low pressure.","The right ventricle has a thinner wall than the left because pulmonary vascular resistance is much lower than systemic resistance.","The left ventricle has a thick, circular myocardium to generate the high pressure needed for the systemic circulation."],"kind":"adaptations"},{"lesson_id":"heart-overview","sort_order":3,"heading":"Functions","body":["The right heart pumps deoxygenated blood to the lungs (pulmonary circulation).","The left heart pumps oxygenated blood to the body (systemic circulation).","The two sides pump in series, so over time they must pump the same volume."],"kind":"functions"},{"lesson_id":"heart-overview","sort_order":4,"heading":"Path of blood","body":["Body → superior/inferior vena cava → right atrium → tricuspid valve → right ventricle → pulmonary valve → pulmonary trunk → lungs → pulmonary veins → left atrium → mitral valve → left ventricle → aortic valve → aorta → body."],"kind":"text"},{"lesson_id":"heart-valves","sort_order":0,"heading":"Atrioventricular valves","body":["The tricuspid valve (right) has three cusps; the mitral (bicuspid) valve (left) has two. Their cusps are tethered by chordae tendineae to papillary muscles."],"kind":"characteristics"},{"lesson_id":"heart-valves","sort_order":1,"heading":"Semilunar valves","body":["The pulmonary and aortic valves each have three pocket-like cusps and no chordae. Behind the aortic valve cusps are the aortic sinuses, from two of which the coronary arteries arise."],"kind":"characteristics"},{"lesson_id":"heart-valves","sort_order":2,"heading":"Adaptations","body":["Papillary muscles contract with the ventricle and pull on the chordae, preventing cusps from prolapsing into the atrium under high ventricular pressure.","Semilunar cusps are shaped like pockets: back-pressure fills them and presses their edges together."],"kind":"adaptations"},{"lesson_id":"heart-valves","sort_order":3,"heading":"Conduction pathway","body":["Sinoatrial (SA) node → atrial myocardium → atrioventricular (AV) node (conduction is delayed here, allowing the ventricles to fill) → bundle of His → right and left bundle branches → Purkinje fibres → ventricular myocardium.","The fibrous skeleton of the heart electrically insulates atria from ventricles, so the AV node and bundle are normally the only pathway between them."],"kind":"functions"},{"lesson_id":"heart-valves","sort_order":4,"heading":"Heart sounds","body":["The first heart sound (\"lub\") is produced mainly by closure of the AV valves at the start of ventricular systole; the second (\"dub\") by closure of the semilunar valves at the start of diastole."],"kind":"text"},{"lesson_id":"great-vessels-circulation","sort_order":0,"heading":"Characteristics","body":["Arteries carry blood away from the heart; veins carry blood towards it. Colour and oxygen content depend on the circuit, not on the vessel type.","Pulmonary trunk → right and left pulmonary arteries (deoxygenated). Pulmonary veins → left atrium (oxygenated). Aorta (oxygenated). Venae cavae (deoxygenated)."],"kind":"characteristics"},{"lesson_id":"great-vessels-circulation","sort_order":1,"heading":"Adaptations","body":["The aorta and other elastic arteries have abundant elastin: they expand in systole and recoil in diastole, which keeps blood moving during ventricular relaxation.","Veins have thinner walls and larger lumens, and many medium-sized veins have valves."],"kind":"adaptations"},{"lesson_id":"great-vessels-circulation","sort_order":2,"heading":"Functions","body":["Pulmonary circulation: gas exchange at the alveolar capillaries.","Systemic circulation: delivery of oxygen and nutrients to tissues and return of carbon dioxide and wastes."],"kind":"functions"},{"lesson_id":"cardiac-cycle","sort_order":0,"heading":"Phases","body":["Ventricular filling: AV valves open; blood flows passively from atria into ventricles; atrial systole at the end tops up the filling.","Isovolumetric contraction: ventricles begin to contract; AV valves close; all valves are closed and volume stays constant while pressure rises.","Ejection: ventricular pressure exceeds aortic and pulmonary pressure; semilunar valves open and blood is ejected.","Isovolumetric relaxation: ventricles relax; semilunar valves close; all valves are closed while pressure falls until AV valves open again."],"kind":"text"},{"lesson_id":"cardiac-cycle","sort_order":1,"heading":"Functions and key relationships","body":["Cardiac output = stroke volume × heart rate.","In a typical resting adult the cycle lasts roughly 0.8 s at 75 beats per minute, with ventricular systole lasting around a third to a half of the cycle (textbook values vary with heart rate)."],"kind":"functions"},{"lesson_id":"cardiac-cycle","sort_order":2,"heading":"Simplification used in this app","body":["The 3D animation is a teaching schematic. It slows the cycle and exaggerates chamber movement to make the phases visible; real chambers change volume rather than simply shrinking in size."],"kind":"text"},{"lesson_id":"bone-classification","sort_order":0,"heading":"Classification by shape","body":["Long bones (humerus, femur): length greater than width. Short bones (carpals, tarsals). Flat bones (skull vault, sternum, scapula). Irregular bones (vertebrae). Sesamoid bones (patella), which develop within tendons."],"kind":"characteristics"},{"lesson_id":"bone-classification","sort_order":1,"heading":"Parts of a long bone","body":["Diaphysis (shaft) with a medullary cavity; epiphyses (ends); metaphyses between them, adjacent to the growth plate (epiphyseal cartilage) in a growing bone.","The outer surface is covered by periosteum (except at articular surfaces, which are covered by hyaline cartilage); the medullary cavity is lined by endosteum."],"kind":"characteristics"},{"lesson_id":"bone-classification","sort_order":2,"heading":"Adaptations","body":["Compact bone forms a thick cortex around the shaft and resists bending and torsion.","Spongy (cancellous) bone at the ends has trabeculae aligned with lines of stress, giving strength with less weight and housing red marrow."],"kind":"adaptations"},{"lesson_id":"bone-classification","sort_order":3,"heading":"Functions","body":["Support, protection, leverage, mineral storage (calcium, phosphate) and haematopoiesis."],"kind":"functions"},{"lesson_id":"axial-skeleton","sort_order":0,"heading":"Vertebral column","body":["7 cervical, 12 thoracic, 5 lumbar, 5 sacral (fused) and usually 4 coccygeal vertebrae. Primary curvatures (thoracic and sacral kyphoses) are present in the fetus; secondary curvatures (cervical and lumbar lordoses) develop after birth."],"kind":"characteristics"},{"lesson_id":"axial-skeleton","sort_order":1,"heading":"Adaptations","body":["Vertebral bodies increase in size from cervical to lumbar regions as the load they carry increases.","Thoracic vertebrae have costal facets for ribs; lumbar vertebrae have large bodies and allow flexion and extension."],"kind":"adaptations"},{"lesson_id":"axial-skeleton","sort_order":2,"heading":"Thoracic cage","body":["12 pairs of ribs: 7 true, 3 false, 2 floating. The sternum has a manubrium, body and xiphoid process; the sternal angle marks the level of the 2nd costal cartilage."],"kind":"characteristics"},{"lesson_id":"axial-skeleton","sort_order":3,"heading":"Functions","body":["The axial skeleton supports the head and trunk, protects the brain, spinal cord and thoracic viscera, and provides attachment for muscles of respiration and posture."],"kind":"functions"},{"lesson_id":"upper-limb-bones","sort_order":0,"heading":"Characteristics","body":["Pectoral girdle: clavicle and scapula. Arm: humerus. Forearm: radius (lateral) and ulna (medial). The sternoclavicular joint is the only bony articulation between the upper limb and the axial skeleton."],"kind":"characteristics"},{"lesson_id":"upper-limb-bones","sort_order":1,"heading":"Adaptations","body":["The shoulder (glenohumeral) joint has a shallow socket and a large humeral head, giving great mobility but less stability, hence frequent dislocation.","The elbow's trochlear notch grips the trochlea, giving stable flexion and extension; the radius rotates around the ulna for pronation and supination."],"kind":"adaptations"},{"lesson_id":"upper-limb-bones","sort_order":2,"heading":"Clinical relevance","body":["Clavicle fractures are common after falls onto the shoulder. Surgical neck of humerus fractures may damage the axillary nerve. Colles fracture is a distal radial fracture, usually after a fall onto an outstretched hand."],"kind":"text"},{"lesson_id":"lower-limb-bones","sort_order":0,"heading":"Characteristics","body":["Hip bone: ilium, ischium and pubis, joined in the acetabulum. Femur: head, neck, greater and lesser trochanters, shaft, condyles. Leg: tibia (medial, weight-bearing) and fibula (lateral)."],"kind":"characteristics"},{"lesson_id":"lower-limb-bones","sort_order":1,"heading":"Adaptations","body":["The acetabulum is deep and the hip joint strongly stabilised by ligaments, which suits weight-bearing and locomotion.","The patella increases the mechanical advantage of quadriceps femoris."],"kind":"adaptations"},{"lesson_id":"lower-limb-bones","sort_order":2,"heading":"Clinical relevance","body":["Femoral neck fractures can disrupt blood supply to the femoral head, causing avascular necrosis. The common fibular nerve is vulnerable around the neck of the fibula."],"kind":"text"},{"lesson_id":"bone-histology","sort_order":0,"heading":"Compact bone","body":["The osteon (Haversian system) is a cylinder of concentric lamellae around a central (Haversian) canal containing vessels and nerves. Osteocytes sit in lacunae and communicate through canaliculi. Perforating (Volkmann) canals connect adjacent Haversian canals."],"kind":"characteristics"},{"lesson_id":"bone-histology","sort_order":1,"heading":"Adaptations","body":["Concentric lamellae with collagen running in alternating directions make bone resistant to torsion. Canaliculi allow nutrient exchange across the calcified matrix."],"kind":"adaptations"},{"lesson_id":"bone-histology","sort_order":2,"heading":"Cardiac muscle","body":["Branching, striated cells with one or two central nuclei, joined end to end at intercalated discs."],"kind":"characteristics"},{"lesson_id":"bone-histology","sort_order":3,"heading":"Functions","body":["Bone supports and stores minerals; cardiac muscle contracts rhythmically and continuously to pump blood."],"kind":"functions"},{"lesson_id":"embryo-early","sort_order":0,"heading":"Key events","body":["Fertilisation usually occurs in the ampulla of the uterine tube, producing a zygote. Cleavage divides the zygote into blastomeres; a morula forms and then a blastocyst, which implants in the endometrium at the end of the first week.","During the third week, gastrulation converts the bilaminar embryonic disc (epiblast and hypoblast) into a trilaminar disc with ectoderm, mesoderm and endoderm."],"kind":"text"},{"lesson_id":"embryo-early","sort_order":1,"heading":"Germ layer derivatives (examples)","body":["Ectoderm: epidermis, nervous system (via neurulation). Mesoderm: muscle, bone, cardiovascular system, kidneys. Endoderm: epithelial lining of the gut and respiratory tract; liver and pancreas parenchyma."],"kind":"characteristics"},{"lesson_id":"embryo-heart","sort_order":0,"heading":"Key events","body":["The heart develops from splanchnic mesoderm (the cardiogenic area). Paired endocardial tubes fuse into a single heart tube, which begins to beat around the fourth week.","The tube loops (bulbus cordis and ventricle move ventrally and to the right), bringing the future chambers into positions resembling the adult heart.","Septation divides the atrium (septum primum and secundum), the atrioventricular canal (endocardial cushions), the ventricles (muscular and membranous interventricular septum) and the outflow tract (aorticopulmonary septum)."],"kind":"text"},{"lesson_id":"embryo-heart","sort_order":1,"heading":"Clinical relevance","body":["Failure of septation causes atrial and ventricular septal defects, the most common congenital heart malformations. Abnormal outflow-tract septation can cause conditions such as persistent truncus arteriosus or transposition of the great arteries."],"kind":"text"},{"lesson_id":"embryo-fetal-circulation","sort_order":0,"heading":"Characteristics","body":["Oxygenated blood from the placenta travels in the umbilical vein; much of it bypasses the liver through the ductus venosus into the inferior vena cava.","In the right atrium, a large part of this blood crosses the foramen ovale into the left atrium. Blood that enters the pulmonary trunk largely bypasses the high-resistance fetal lungs through the ductus arteriosus into the aorta."],"kind":"characteristics"},{"lesson_id":"embryo-fetal-circulation","sort_order":1,"heading":"Adaptations","body":["Fetal lungs are fluid-filled with high vascular resistance, so only a small fraction of right ventricular output goes to the lungs. The shunts divert blood to the systemic circulation."],"kind":"adaptations"},{"lesson_id":"embryo-fetal-circulation","sort_order":2,"heading":"Changes at birth","body":["Lungs expand, pulmonary resistance falls and pulmonary blood flow rises; left atrial pressure exceeds right atrial pressure and the foramen ovale closes, leaving the fossa ovalis. The ductus arteriosus constricts and becomes the ligamentum arteriosum; the ductus venosus becomes the ligamentum venosum; the umbilical vein becomes the ligamentum teres of the liver."],"kind":"functions"},{"lesson_id":"embryo-fetal-circulation","sort_order":3,"heading":"Clinical relevance","body":["A patent ductus arteriosus or patent foramen ovale are persisting fetal shunts."],"kind":"text"}]$j$::jsonb) on conflict do nothing;
insert into public.histology_images ("id", "name", "classification", "data") select "id", "name", "classification", "data" from jsonb_populate_recordset(null::public.histology_images, $j$[{"id":"epithelial","name":"Epithelial tissue","classification":"Basic tissue: epithelium (shown: simple columnar epithelium)","data":{"id":"epithelial","name":"Epithelial tissue","classification":"Basic tissue: epithelium (shown: simple columnar epithelium)","cellular_characteristics":["Cells are closely packed with little extracellular matrix.","Cells show polarity: apical, lateral and basal surfaces.","Rest on a basement membrane; the tissue itself has no blood vessels (avascular).","Classified by number of layers (simple, stratified) and cell shape (squamous, cuboidal, columnar)."],"structural_adaptations":["Tight junctions and desmosomes join cells to form a barrier and resist mechanical stress.","Simple squamous epithelium is thin, which favours diffusion (alveoli, capillaries).","Microvilli on absorptive columnar cells increase surface area (small intestine).","Stratified squamous keratinised epithelium resists abrasion (epidermis)."],"functions":["Protection","Absorption","Secretion","Selective barrier and transport","Sensation"],"locations":["Lining of the gut (simple columnar)","Alveoli and capillaries (simple squamous)","Epidermis (keratinised stratified squamous)","Kidney tubules (simple cuboidal)"],"identification_features":["Sheets of closely packed cells","Cells sitting on a pink basement membrane","A free (apical) surface facing a lumen or the exterior"],"related_organs":["Small intestine","Lung","Skin","Kidney"],"related_structure_ids":[],"image":{"kind":"schematic","credit":"Original schematic by CymorTechServices","licence":"MIT (same as this project)","magnification":"Not applicable (schematic, not to scale)","stain":"Not applicable (schematic)","labels":[{"x":200,"y":82,"text":"Apical surface"},{"x":98,"y":145,"text":"Nucleus (basal)"},{"x":290,"y":172,"text":"Basement membrane"},{"x":200,"y":230,"text":"Lamina propria (connective tissue)"}]},"practice":[{"question":"Which feature distinguishes epithelium from connective tissue?","answer":"Epithelium is cellular with little matrix, sits on a basement membrane and is avascular."},{"question":"Why does the alveolar wall use simple squamous epithelium?","answer":"A single thin layer of flat cells gives a short diffusion distance for gas exchange."}]}},{"id":"connective","name":"Connective tissue","classification":"Basic tissue: connective tissue (shown: loose connective tissue)","data":{"id":"connective","name":"Connective tissue","classification":"Basic tissue: connective tissue (shown: loose connective tissue)","cellular_characteristics":["Cells are scattered in an abundant extracellular matrix of fibres and ground substance.","Fibroblasts produce collagen and elastic fibres.","Other cells include macrophages, mast cells and plasma cells.","Fibres: collagen (strength), elastic (recoil), reticular (supporting mesh)."],"structural_adaptations":["Loose connective tissue has a loose fibre arrangement, flexible and rich in cells and vessels: suits support of epithelia.","Dense regular connective tissue has parallel collagen bundles, resisting tension in one direction (tendons)."],"functions":["Support and binding","Defence","Storage (adipose)","Transport (blood is a specialised connective tissue)"],"locations":["Beneath epithelia (lamina propria)","Around organs and vessels","Tendons and ligaments (dense regular)","Dermis (dense irregular)"],"identification_features":["Few cells scattered in a pink fibre-rich matrix","Wavy collagen fibres","Spindle-shaped fibroblast nuclei"],"related_organs":["Skin","Gut wall","Tendons"],"related_structure_ids":[],"image":{"kind":"schematic","credit":"Original schematic by CymorTechServices","licence":"MIT (same as this project)","magnification":"Not applicable (schematic, not to scale)","stain":"Not applicable (schematic)","labels":[{"x":110,"y":90,"text":"Collagen fibres"},{"x":255,"y":140,"text":"Fibroblast"},{"x":305,"y":220,"text":"Capillary"},{"x":90,"y":230,"text":"Ground substance"}]},"practice":[{"question":"Which cell produces collagen in connective tissue?","answer":"The fibroblast."},{"question":"Why are tendons made of dense regular connective tissue?","answer":"Parallel collagen bundles resist strong tension in one direction."}]}},{"id":"muscle","name":"Muscle tissue","classification":"Basic tissue: muscle (shown: skeletal, cardiac and smooth muscle)","data":{"id":"muscle","name":"Muscle tissue","classification":"Basic tissue: muscle (shown: skeletal, cardiac and smooth muscle)","cellular_characteristics":["Skeletal: long, multinucleated, striated fibres with peripheral nuclei.","Cardiac: branched, striated cells with one or two central nuclei and intercalated discs.","Smooth: spindle-shaped cells with a single central nucleus, no striations."],"structural_adaptations":["Skeletal fibres are multinucleate and sarcomeres are in register, giving powerful voluntary contraction.","Intercalated discs (desmosomes and gap junctions) bind cardiac cells mechanically and electrically.","Smooth muscle cells can contract slowly and be sustained, suited to hollow organs."],"functions":["Movement","Posture","Pumping blood (cardiac)","Moving substances through hollow organs (smooth)"],"locations":["Skeletal muscles attached to bone","Wall of the heart (cardiac)","Walls of the gut, vessels and uterus (smooth)"],"identification_features":["Striations in skeletal and cardiac muscle","Peripheral nuclei: skeletal","Intercalated discs: cardiac","Spindle cells without striations: smooth"],"related_organs":["Heart","Stomach","Biceps brachii"],"related_structure_ids":["cardiac-muscle"],"image":{"kind":"schematic","credit":"Original schematic by CymorTechServices","licence":"MIT (same as this project)","magnification":"Not applicable (schematic, not to scale)","stain":"Not applicable (schematic)","labels":[{"x":70,"y":17,"text":"Skeletal: peripheral nuclei"},{"x":210,"y":124,"text":"Cardiac: intercalated disc"},{"x":100,"y":255,"text":"Smooth: spindle cell"}]},"practice":[{"question":"Which muscle type has intercalated discs?","answer":"Cardiac muscle."},{"question":"Where are the nuclei in skeletal muscle fibres?","answer":"At the periphery, just under the sarcolemma."}]}},{"id":"nervous","name":"Nervous tissue","classification":"Basic tissue: nervous tissue (shown: myelinated multipolar neuron)","data":{"id":"nervous","name":"Nervous tissue","classification":"Basic tissue: nervous tissue (shown: myelinated multipolar neuron)","cellular_characteristics":["Neurons: soma, dendrites and a single axon.","Glial cells support neurons: astrocytes, oligodendrocytes, microglia, ependymal cells (CNS) and Schwann and satellite cells (PNS).","Myelin from oligodendrocytes (CNS) or Schwann cells (PNS) insulates axons; gaps are nodes of Ranvier."],"structural_adaptations":["Dendrites increase receptive surface area.","Long axons carry impulses over distance.","Myelin and nodes of Ranvier allow fast saltatory conduction."],"functions":["Receiving, integrating and transmitting signals","Coordination of body functions"],"locations":["Brain","Spinal cord","Peripheral nerves and ganglia"],"identification_features":["Large neuronal cell bodies with a prominent nucleolus","Neuropil (a network of processes)","Small, dark glial nuclei"],"related_organs":["Brain","Spinal cord","Peripheral nerves"],"related_structure_ids":[],"image":{"kind":"schematic","credit":"Original schematic by CymorTechServices","licence":"MIT (same as this project)","magnification":"Not applicable (schematic, not to scale)","stain":"Not applicable (schematic)","labels":[{"x":130,"y":170,"text":"Cell body (soma)"},{"x":150,"y":150,"text":"Nucleus"},{"x":70,"y":90,"text":"Dendrites"},{"x":225,"y":140,"text":"Myelin sheath"},{"x":312,"y":150,"text":"Node of Ranvier"},{"x":186,"y":150,"text":"Axon"}]},"practice":[{"question":"Which cells myelinate axons in the peripheral nervous system?","answer":"Schwann cells."},{"question":"What are the gaps in the myelin sheath called?","answer":"Nodes of Ranvier."}]}},{"id":"blood","name":"Blood","classification":"Specialised connective tissue (shown: peripheral blood elements)","data":{"id":"blood","name":"Blood","classification":"Specialised connective tissue (shown: peripheral blood elements)","cellular_characteristics":["Erythrocytes: anucleate biconcave discs in mature mammals.","Leukocytes: neutrophils (multilobed nucleus), lymphocytes (large round nucleus, thin rim of cytoplasm), monocytes, eosinophils, basophils.","Platelets: small cell fragments from megakaryocytes.","The liquid matrix is plasma."],"structural_adaptations":["The biconcave shape of red cells increases surface area for gas exchange and allows flexibility in capillaries.","Lack of a nucleus provides more room for haemoglobin."],"functions":["Gas transport","Defence","Haemostasis","Transport of nutrients, hormones and wastes"],"locations":["Circulates in the heart and blood vessels","Formed in red bone marrow"],"identification_features":["Pink anucleate discs with a central pale area (red cells)","Nucleated white cells with distinct nuclear shapes","Tiny purple granular fragments (platelets)"],"related_organs":["Heart","Bone marrow","Spleen"],"related_structure_ids":["left-ventricle"],"image":{"kind":"schematic","credit":"Original schematic by CymorTechServices","licence":"MIT (same as this project)","magnification":"Not applicable (schematic, not to scale)","stain":"Not applicable (schematic)","labels":[{"x":110,"y":95,"text":"Erythrocyte"},{"x":255,"y":90,"text":"Neutrophil"},{"x":100,"y":220,"text":"Lymphocyte"},{"x":300,"y":215,"text":"Platelets"}]},"practice":[{"question":"Why are mature red blood cells biconcave?","answer":"The shape increases surface area for gas exchange and allows the cell to deform in capillaries."},{"question":"Which cell has a multilobed nucleus?","answer":"The neutrophil."}]}},{"id":"cartilage","name":"Cartilage","classification":"Specialised connective tissue (shown: hyaline cartilage)","data":{"id":"cartilage","name":"Cartilage","classification":"Specialised connective tissue (shown: hyaline cartilage)","cellular_characteristics":["Chondrocytes lie in lacunae within a firm matrix of type II collagen and proteoglycans.","Chondroblasts produce matrix at the periphery.","Cells may appear in isogenous groups after division.","Avascular: nutrients diffuse through the matrix from the perichondrium."],"structural_adaptations":["The proteoglycan matrix binds water, making cartilage firm yet resilient to compression.","Being avascular and surrounded by perichondrium, it grows by appositional and interstitial growth."],"functions":["Support","Smooth articular surfaces","Models for endochondral bone growth"],"locations":["Articular surfaces","Costal cartilages","Trachea and larynx","Growth plates"],"identification_features":["Glassy, homogeneous matrix","Chondrocytes in lacunae, often in pairs or groups","Perichondrium (except articular cartilage)"],"related_organs":["Trachea","Ribs","Joints"],"related_structure_ids":["rib-cage"],"image":{"kind":"schematic","credit":"Original schematic by CymorTechServices","licence":"MIT (same as this project)","magnification":"Not applicable (schematic, not to scale)","stain":"Not applicable (schematic)","labels":[{"x":200,"y":40,"text":"Perichondrium"},{"x":110,"y":150,"text":"Chondrocyte in lacuna"},{"x":270,"y":195,"text":"Isogenous group"},{"x":320,"y":120,"text":"Matrix"}]},"practice":[{"question":"Why does cartilage heal slowly?","answer":"It is avascular, so nutrients reach cells only by diffusion."}]}},{"id":"bone","name":"Bone tissue","classification":"Specialised connective tissue (shown: compact bone osteon)","data":{"id":"bone","name":"Bone tissue","classification":"Specialised connective tissue (shown: compact bone osteon)","cellular_characteristics":["Osteoblasts form matrix; osteocytes maintain it from lacunae; osteoclasts resorb bone.","Matrix: type I collagen with hydroxyapatite mineral.","Osteons (Haversian systems) are the structural unit of compact bone."],"structural_adaptations":["Concentric lamellae with differing collagen orientation resist torsion.","Canaliculi connect lacunae and the central canal so osteocytes obtain nutrients despite the calcified matrix.","Remodelling lets bone adapt to mechanical load."],"functions":["Support","Protection","Mineral storage","Haematopoiesis (marrow)"],"locations":["Shafts of long bones (compact bone)","Epiphyses (spongy bone)"],"identification_features":["Concentric rings around a central canal","Small dark osteocyte lacunae between rings","Interstitial lamellae between osteons"],"related_organs":["Femur","Humerus","Skull"],"related_structure_ids":["femur","humerus"],"image":{"kind":"schematic","credit":"Original schematic by CymorTechServices","licence":"MIT (same as this project)","magnification":"Not applicable (schematic, not to scale)","stain":"Not applicable (schematic)","labels":[{"x":200,"y":150,"text":"Central (Haversian) canal"},{"x":244,"y":106,"text":"Concentric lamellae"},{"x":156,"y":106,"text":"Osteocyte in lacuna"},{"x":340,"y":255,"text":"Interstitial lamellae"}]},"practice":[{"question":"What occupies the central canal of an osteon?","answer":"Blood vessels and nerves."},{"question":"What is the function of canaliculi?","answer":"They connect lacunae so osteocytes can exchange nutrients and wastes."}]}}]$j$::jsonb) on conflict do nothing;
insert into public.animations ("id", "title", "system_id", "kind", "duration_s", "summary", "steps", "structure_ids", "simplifications") select "id", "title", "system_id", "kind", "duration_s", "summary", "steps", "structure_ids", "simplifications" from jsonb_populate_recordset(null::public.animations, $j$[{"id":"cardiac-cycle","title":"The cardiac cycle (3D)","system_id":"cardiovascular","kind":"cardiac","duration_s":8,"summary":"A 3D teaching schematic of one heartbeat: atrial systole, isovolumetric contraction, ejection, isovolumetric relaxation and filling.","steps":[{"at":0,"title":"Atrial systole","description":"The atria contract and top up ventricular filling. AV valves are open; the aortic and pulmonary valves are closed."},{"at":0.12,"title":"Isovolumetric contraction","description":"The ventricles begin to contract. The AV valves close (first heart sound) but pressure has not yet exceeded that in the aorta and pulmonary trunk, so all four valves are closed."},{"at":0.17,"title":"Ventricular ejection","description":"Ventricular pressure exceeds arterial pressure. The aortic and pulmonary valves open and blood is ejected into the aorta and pulmonary trunk."},{"at":0.5,"title":"Isovolumetric relaxation","description":"The ventricles relax and the semilunar valves close (second heart sound). All valves are closed while pressure falls."},{"at":0.57,"title":"Ventricular filling","description":"Ventricular pressure falls below atrial pressure. The AV valves open and blood flows from the atria into the ventricles."}],"structure_ids":["left-ventricle","right-ventricle","left-atrium","right-atrium","mitral-valve","tricuspid-valve","aortic-valve","pulmonary-valve"],"simplifications":["Timings are proportional and the loop is slowed for teaching (at 1x one cycle takes 8 s).","Chambers change size in the model; real chambers change volume with a more complex wall motion.","Valve open/closed state is indicated by colour (green = open, red = closed), not by animated cusps."]},{"id":"circulation","title":"Pulmonary and systemic circulation","system_id":"cardiovascular","kind":"circulation","duration_s":12,"summary":"Simplified flow diagram showing blood moving around the two circuits in series.","steps":[{"at":0,"title":"Systemic arteries","description":"The left ventricle ejects oxygenated blood into the aorta, which distributes it through arteries to the body."},{"at":0.207,"title":"Systemic capillaries","description":"Oxygen and nutrients leave the blood and carbon dioxide enters it at the tissue capillaries."},{"at":0.268,"title":"Systemic veins","description":"Deoxygenated blood returns through veins to the superior and inferior venae cavae and the right atrium."},{"at":0.51,"title":"Pulmonary arteries","description":"The right ventricle pumps blood through the pulmonary trunk and arteries to the lungs."},{"at":0.701,"title":"Pulmonary capillaries","description":"Gas exchange: carbon dioxide leaves the blood and oxygen enters it across the alveolar wall."},{"at":0.763,"title":"Pulmonary veins","description":"Oxygenated blood returns via the pulmonary veins to the left atrium."}],"structure_ids":["aorta","pulmonary-trunk","superior-vena-cava","inferior-vena-cava","pulmonary-veins"],"simplifications":["Vessel sizes, speeds and capillary beds are not to scale.","The two circuits are drawn side by side; in reality both sides of the heart beat simultaneously.","Dots show direction of flow only; they do not represent real velocity."]},{"id":"breathing","title":"Breathing: diaphragm and thorax","system_id":"respiratory","kind":"breathing","duration_s":6,"summary":"Side-view schematic of quiet breathing: diaphragm and ribs change thoracic volume.","steps":[{"at":0,"title":"Inspiration","description":"The diaphragm contracts and flattens; external intercostal muscles lift the ribs. Thoracic volume rises, intrapleural and alveolar pressure fall, and air flows in."},{"at":0.4,"title":"Expiration","description":"In quiet breathing expiration is passive. The diaphragm relaxes and returns to its dome shape; the ribs descend; the lungs recoil and air flows out."}],"structure_ids":["rib-cage","sternum"],"simplifications":["Lung and diaphragm shapes are heavily simplified.","Only the antero-posterior change is drawn; the transverse expansion of the lower ribs is not shown.","Forced breathing, which recruits accessory muscles, is not shown."]},{"id":"elbow","title":"Elbow flexion and extension","system_id":"muscular","kind":"joint","duration_s":8,"summary":"The elbow as a hinge joint: biceps brachii shortens to flex, triceps brachii shortens to extend.","steps":[{"at":0,"title":"Flexion","description":"Biceps brachii (agonist) contracts and shortens; triceps brachii (antagonist) relaxes. The forearm moves towards the arm around the hinge axis of the elbow."},{"at":0.5,"title":"Extension","description":"Triceps brachii contracts and shortens; biceps relaxes and lengthens. The forearm returns to the extended position."}],"structure_ids":["humerus","radius","ulna"],"simplifications":["Only a single hinge axis is drawn; pronation and supination at the radio-ulnar joints are not shown.","Muscle bulk is shown as a simple bulge; sarcomere-level contraction is not animated."]},{"id":"peristalsis","title":"Peristalsis","system_id":"digestive","kind":"peristalsis","duration_s":8,"summary":"A wave of coordinated contraction behind a bolus and relaxation ahead of it moves contents along the gut.","steps":[{"at":0,"title":"Bolus enters","description":"Stretch of the wall by the bolus triggers a reflex in the enteric nervous system."},{"at":0.3,"title":"Contraction behind, relaxation ahead","description":"Circular muscle contracts behind the bolus while longitudinal muscle ahead contracts and circular muscle relaxes, widening the lumen."},{"at":0.7,"title":"Bolus propelled","description":"The wave of contraction pushes the bolus forward along the tube."}],"structure_ids":[],"simplifications":["Shows a generic tube, not a specific part of the gut.","Real peristalsis involves a coordinated interplay of nerves, hormones and pacemaker cells, which is not shown."]}]$j$::jsonb) on conflict do nothing;
insert into public.quizzes ("id", "title", "topic") select "id", "title", "topic" from jsonb_populate_recordset(null::public.quizzes, $j$[{"id":"quiz-cardiovascular","title":"Cardiovascular quiz","topic":"cardiovascular"},{"id":"quiz-skeletal","title":"Skeletal quiz","topic":"skeletal"},{"id":"quiz-histology","title":"Histology quiz","topic":"histology"}]$j$::jsonb) on conflict do nothing;
insert into public.questions ("id", "quiz_id", "type", "topic", "difficulty", "prompt", "explanation", "correct", "structure_id", "payload") select "id", "quiz_id", "type", "topic", "difficulty", "prompt", "explanation", "correct", "structure_id", "payload" from jsonb_populate_recordset(null::public.questions, $j$[{"id":"cv-01","quiz_id":"quiz-cardiovascular","type":"mcq","topic":"cardiovascular","difficulty":"beginner","prompt":"Which heart chamber receives blood from the superior and inferior venae cavae?","explanation":"Both venae cavae drain deoxygenated systemic blood into the right atrium.","correct":"a","structure_id":"right-atrium","payload":{}},{"id":"cv-02","quiz_id":"quiz-cardiovascular","type":"mcq","topic":"cardiovascular","difficulty":"beginner","prompt":"Which vessels return oxygenated blood from the lungs to the heart?","explanation":"The pulmonary veins carry oxygenated blood from the lungs into the left atrium.","correct":"a","structure_id":"pulmonary-veins","payload":{}},{"id":"cv-03","quiz_id":"quiz-cardiovascular","type":"tf","topic":"cardiovascular","difficulty":"beginner","prompt":"The wall of the left ventricle is thicker than the wall of the right ventricle.","explanation":"The left ventricle pumps against the high resistance of the systemic circulation and therefore has a much thicker myocardium.","correct":"a","structure_id":"left-ventricle","payload":{}},{"id":"cv-04","quiz_id":"quiz-cardiovascular","type":"mcq","topic":"cardiovascular","difficulty":"intermediate","prompt":"Which valve lies between the left atrium and the left ventricle?","explanation":"The mitral (bicuspid) valve is the left atrioventricular valve.","correct":"b","structure_id":"mitral-valve","payload":{}},{"id":"cv-05","quiz_id":"quiz-cardiovascular","type":"mcq","topic":"cardiovascular","difficulty":"intermediate","prompt":"What is the main function of the chordae tendineae?","explanation":"Chordae tendineae tether the AV valve cusps to the papillary muscles so the cusps cannot prolapse when the ventricle contracts.","correct":"b","structure_id":null,"payload":{}},{"id":"cv-06","quiz_id":"quiz-cardiovascular","type":"tf","topic":"cardiovascular","difficulty":"intermediate","prompt":"The tricuspid valve has two cusps.","explanation":"The tricuspid valve has three cusps; the mitral valve is the one with two.","correct":"b","structure_id":"tricuspid-valve","payload":{}},{"id":"cv-07","quiz_id":"quiz-cardiovascular","type":"mcq","topic":"cardiovascular","difficulty":"beginner","prompt":"Which structure is the normal pacemaker of the heart?","explanation":"The sinoatrial node depolarises spontaneously faster than other cardiac tissue and sets the heart rate.","correct":"b","structure_id":"sinoatrial-node","payload":{}},{"id":"cv-08","quiz_id":"quiz-cardiovascular","type":"fill","topic":"cardiovascular","difficulty":"intermediate","prompt":"The ________ valve lies between the left ventricle and the aorta.","explanation":"The aortic (semilunar) valve guards the outflow of the left ventricle.","correct":null,"structure_id":"aortic-valve","payload":{"accepted":["aortic","aortic valve","aortic semilunar"]}},{"id":"cv-09","quiz_id":"quiz-cardiovascular","type":"match","topic":"cardiovascular","difficulty":"intermediate","prompt":"Match each structure to its function.","explanation":"Each structure was described in the heart notes: the SA node is the pacemaker, the aortic valve prevents backflow, chordae tendineae tether valve cusps, and coronary arteries perfuse the heart muscle.","correct":null,"structure_id":null,"payload":{"pairs":[{"left":"Sinoatrial node","right":"Initiates the heartbeat"},{"left":"Aortic valve","right":"Prevents backflow from the aorta into the left ventricle"},{"left":"Chordae tendineae","right":"Anchor AV valve cusps to papillary muscles"},{"left":"Coronary arteries","right":"Supply blood to the myocardium"}]}},{"id":"cv-10","quiz_id":"quiz-cardiovascular","type":"identify","topic":"cardiovascular","difficulty":"beginner","prompt":"Which structure is marked by the highlighted pin?","explanation":"Pin 7 is on the large, thick-walled chamber forming the apex: the left ventricle.","correct":"b","structure_id":"left-ventricle","payload":{"diagram":"heart","highlight_pin":"7"}},{"id":"cv-11","quiz_id":"quiz-cardiovascular","type":"identify","topic":"cardiovascular","difficulty":"beginner","prompt":"Which structure is marked by the highlighted pin?","explanation":"Pin 4 marks the chamber on the right of the patient (left of the picture) that receives the venae cavae: the right atrium.","correct":"c","structure_id":"right-atrium","payload":{"diagram":"heart","highlight_pin":"4"}},{"id":"cv-12","quiz_id":"quiz-cardiovascular","type":"label","topic":"cardiovascular","difficulty":"intermediate","prompt":"Label the numbered vessels on the diagram.","explanation":"1 = superior vena cava, 2 = aorta (arch), 3 = pulmonary trunk, 8 = inferior vena cava.","correct":null,"structure_id":null,"payload":{"pin_answers":{"1":"a","2":"b","3":"c","8":"d"},"diagram":"heart"}},{"id":"cv-13","quiz_id":"quiz-cardiovascular","type":"mcq","topic":"cardiovascular","difficulty":"advanced","prompt":"During which phase of the cardiac cycle are all four heart valves closed and ventricular volume constant?","explanation":"In isovolumetric contraction the AV valves have just closed but ventricular pressure has not yet exceeded arterial pressure, so the semilunar valves are still shut.","correct":"c","structure_id":null,"payload":{}},{"id":"cv-14","quiz_id":"quiz-cardiovascular","type":"mcq","topic":"cardiovascular","difficulty":"advanced","prompt":"From which part of the aorta do the coronary arteries normally arise?","explanation":"The right and left coronary arteries arise from the right and left aortic sinuses of the ascending aorta.","correct":"b","structure_id":"coronary-arteries","payload":{}},{"id":"cv-15","quiz_id":"quiz-cardiovascular","type":"tf","topic":"cardiovascular","difficulty":"advanced","prompt":"Intercalated discs of cardiac muscle contain gap junctions that allow rapid spread of excitation between cells.","explanation":"Gap junctions provide low-resistance electrical coupling and desmosomes provide mechanical strength.","correct":"a","structure_id":"cardiac-muscle","payload":{}},{"id":"cv-16","quiz_id":"quiz-cardiovascular","type":"mcq","topic":"cardiovascular","difficulty":"intermediate","prompt":"Cardiac output is equal to:","explanation":"Cardiac output (mL/min) = stroke volume (mL/beat) × heart rate (beats/min).","correct":"a","structure_id":null,"payload":{}},{"id":"cv-17","quiz_id":"quiz-cardiovascular","type":"fill","topic":"cardiovascular","difficulty":"beginner","prompt":"The great vein that drains the head, neck and upper limbs into the right atrium is the superior ________.","explanation":"The superior vena cava returns blood from the body above the diaphragm (except the lungs and heart).","correct":null,"structure_id":"superior-vena-cava","payload":{"accepted":["vena cava"]}},{"id":"cv-18","quiz_id":"quiz-cardiovascular","type":"mcq","topic":"cardiovascular","difficulty":"intermediate","prompt":"After birth the foramen ovale closes and leaves a depression in the interatrial septum called the:","explanation":"The fossa ovalis is the remnant of the fetal foramen ovale.","correct":"a","structure_id":"right-atrium","payload":{}},{"id":"cv-19","quiz_id":"quiz-cardiovascular","type":"mcq","topic":"cardiovascular","difficulty":"advanced","prompt":"Which statement about the pulmonary trunk is correct?","explanation":"The pulmonary trunk leaves the right ventricle and divides into the right and left pulmonary arteries.","correct":"a","structure_id":"pulmonary-trunk","payload":{}},{"id":"sk-01","quiz_id":"quiz-skeletal","type":"mcq","topic":"skeletal","difficulty":"beginner","prompt":"How many cervical vertebrae are there in the human vertebral column?","explanation":"There are 7 cervical, 12 thoracic and 5 lumbar vertebrae, plus the sacrum and coccyx.","correct":"b","structure_id":"vertebral-column","payload":{}},{"id":"sk-02","quiz_id":"quiz-skeletal","type":"mcq","topic":"skeletal","difficulty":"beginner","prompt":"What is the common name for the clavicle?","explanation":"The clavicle is the collarbone; the scapula is the shoulder blade; the sternum is the breastbone.","correct":"b","structure_id":"clavicle","payload":{}},{"id":"sk-03","quiz_id":"quiz-skeletal","type":"tf","topic":"skeletal","difficulty":"beginner","prompt":"The patella is a sesamoid bone.","explanation":"The patella develops within the quadriceps femoris tendon, which defines a sesamoid bone.","correct":"a","structure_id":"patella","payload":{}},{"id":"sk-04","quiz_id":"quiz-skeletal","type":"mcq","topic":"skeletal","difficulty":"beginner","prompt":"Which bone of the leg bears most of the body weight?","explanation":"The tibia transmits weight from the femur to the foot; the fibula is slender and mainly for muscle attachment.","correct":"b","structure_id":"tibia","payload":{}},{"id":"sk-05","quiz_id":"quiz-skeletal","type":"mcq","topic":"skeletal","difficulty":"intermediate","prompt":"A Colles fracture is a fracture of which bone?","explanation":"A Colles fracture is a fracture of the distal radius, usually after a fall onto an outstretched hand.","correct":"a","structure_id":"radius","payload":{}},{"id":"sk-06","quiz_id":"quiz-skeletal","type":"fill","topic":"skeletal","difficulty":"intermediate","prompt":"The shaft of a long bone is called the ________.","explanation":"The diaphysis is the shaft; the epiphyses are the ends.","correct":null,"structure_id":null,"payload":{"accepted":["diaphysis"]}},{"id":"sk-07","quiz_id":"quiz-skeletal","type":"match","topic":"skeletal","difficulty":"intermediate","prompt":"Match each bone to its description.","explanation":"These descriptions come from the skeletal notes.","correct":null,"structure_id":null,"payload":{"pairs":[{"left":"Femur","right":"Longest bone in the body"},{"left":"Scapula","right":"Shoulder blade"},{"left":"Ulna","right":"Medial forearm bone in the anatomical position"},{"left":"Sternum","right":"Breastbone"}]}},{"id":"sk-08","quiz_id":"quiz-skeletal","type":"identify","topic":"skeletal","difficulty":"intermediate","prompt":"Which part of the long bone is marked by the highlighted pin?","explanation":"Pin 3 is the hollow centre of the diaphysis: the medullary cavity, which contains marrow.","correct":"c","structure_id":null,"payload":{"diagram":"long-bone","highlight_pin":"3"}},{"id":"sk-09","quiz_id":"quiz-skeletal","type":"label","topic":"skeletal","difficulty":"intermediate","prompt":"Label the numbered parts of the long bone.","explanation":"1 = epiphysis, 2 = diaphysis, 4 = articular cartilage, 5 = periosteum.","correct":null,"structure_id":null,"payload":{"pin_answers":{"1":"a","2":"b","4":"d","5":"e"},"diagram":"long-bone"}},{"id":"sk-10","quiz_id":"quiz-skeletal","type":"tf","topic":"skeletal","difficulty":"beginner","prompt":"There are 12 pairs of ribs in the typical human skeleton.","explanation":"There are 12 pairs: 7 true, 3 false and 2 floating ribs.","correct":"a","structure_id":"rib-cage","payload":{}},{"id":"sk-11","quiz_id":"quiz-skeletal","type":"mcq","topic":"skeletal","difficulty":"advanced","prompt":"A fracture of the surgical neck of the humerus is most likely to endanger which nerve?","explanation":"The axillary nerve winds around the surgical neck of the humerus. The radial nerve lies in the radial groove of the shaft.","correct":"b","structure_id":"humerus","payload":{}},{"id":"sk-12","quiz_id":"quiz-skeletal","type":"mcq","topic":"skeletal","difficulty":"intermediate","prompt":"Which ribs are described as floating ribs?","explanation":"Ribs 11 and 12 have no attachment to the sternum or to another rib's costal cartilage.","correct":"c","structure_id":"rib-cage","payload":{}},{"id":"sk-13","quiz_id":"quiz-skeletal","type":"tf","topic":"skeletal","difficulty":"intermediate","prompt":"The fibula is the main weight-bearing bone of the leg.","explanation":"The tibia is the main weight-bearing bone; the fibula is not.","correct":"b","structure_id":"fibula","payload":{}},{"id":"sk-14","quiz_id":"quiz-skeletal","type":"mcq","topic":"skeletal","difficulty":"intermediate","prompt":"Which pair of vertebral curvatures are secondary curvatures that develop after birth?","explanation":"The cervical and lumbar lordoses develop after birth (holding up the head, sitting and walking); thoracic and sacral kyphoses are primary curvatures.","correct":"b","structure_id":"vertebral-column","payload":{}},{"id":"sk-15","quiz_id":"quiz-skeletal","type":"mcq","topic":"skeletal","difficulty":"advanced","prompt":"Why can a fracture of the femoral neck lead to avascular necrosis of the femoral head?","explanation":"The head receives blood largely from branches of the medial and lateral circumflex femoral arteries that travel along the neck.","correct":"a","structure_id":"femur","payload":{}},{"id":"hi-01","quiz_id":"quiz-histology","type":"mcq","topic":"histology","difficulty":"beginner","prompt":"Which tissue contains intercalated discs?","explanation":"Intercalated discs join cardiac muscle cells end to end.","correct":"c","structure_id":"cardiac-muscle","payload":{}},{"id":"hi-02","quiz_id":"quiz-histology","type":"mcq","topic":"histology","difficulty":"intermediate","prompt":"What is the name of the central channel of an osteon?","explanation":"The central (Haversian) canal contains blood vessels and nerves. Volkmann canals run perpendicularly and connect Haversian canals.","correct":"b","structure_id":null,"payload":{}},{"id":"hi-03","quiz_id":"quiz-histology","type":"mcq","topic":"histology","difficulty":"beginner","prompt":"Which cells are found in lacunae in mature bone?","explanation":"Osteocytes are mature bone cells that live in lacunae. Chondrocytes are the cells of cartilage.","correct":"c","structure_id":null,"payload":{}},{"id":"hi-04","quiz_id":"quiz-histology","type":"tf","topic":"histology","difficulty":"intermediate","prompt":"Hyaline cartilage contains blood vessels within its matrix.","explanation":"Cartilage is avascular; nutrients diffuse through the matrix.","correct":"b","structure_id":null,"payload":{}},{"id":"hi-05","quiz_id":"quiz-histology","type":"mcq","topic":"histology","difficulty":"intermediate","prompt":"Which blood cell is anucleate in mature humans?","explanation":"Mature red blood cells lose their nucleus.","correct":"c","structure_id":null,"payload":{}},{"id":"hi-06","quiz_id":"quiz-histology","type":"mcq","topic":"histology","difficulty":"beginner","prompt":"Which type of epithelium lines the walls of the alveoli?","explanation":"A single thin layer of flat cells provides a short diffusion path for gases.","correct":"a","structure_id":null,"payload":{}},{"id":"hi-07","quiz_id":"quiz-histology","type":"fill","topic":"histology","difficulty":"intermediate","prompt":"The cells of cartilage are called ________.","explanation":"Chondrocytes sit in lacunae in the cartilage matrix.","correct":null,"structure_id":null,"payload":{"accepted":["chondrocytes","chondrocyte"]}},{"id":"hi-08","quiz_id":"quiz-histology","type":"mcq","topic":"histology","difficulty":"intermediate","prompt":"Which cells form the myelin sheath around axons of the peripheral nervous system?","explanation":"Schwann cells myelinate peripheral axons; oligodendrocytes myelinate axons in the CNS.","correct":"b","structure_id":null,"payload":{}}]$j$::jsonb) on conflict do nothing;
